                    ))
                ) : (
                    <div className="py-12 text-center">
                        <p className="text-sm text-light-text-secondary dark:text-dark-text-secondary italic">No se han definido tareas para este proyecto.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

