                const diffMinutes = (occurrenceDateTime.getTime() - now.getTime()) / (1000 * 60);
                notificationIntervals.forEach(interval => {
                    if (diffMinutes > interval.minutes - 1 && diffMinutes <= interval.minutes) {
                        if (interval.id === '1d') {
