    if (error) throw error;
    return data;
};

export const updatePassword = async (password: Omit<PasswordItem, 'user_id'>): Promise<PasswordItem> => {
    const { id, ...passwordData } = password;
    const { data, error = { message: 'Unknown error' } as any } = await supabase.from('passwords').update(passwordData).eq('id', id).select().single();
    if (error) throw error;
    return data;
};

export const deletePassword = async (passwordId: string): Promise<void> => {
    const { error = { message: 'Unknown error' } as any } = await supabase.from('passwords').delete().eq('id', passwordId);
    if (error) throw error;
};

export const getMasterPasswordHash = async (): Promise<string | null> => {
    const targetId = await getVaultOwnerId();
    const { data, error } = await supabase.from('passwords').select('password_ct').eq('user_id', targetId).eq('service', 'MASTER').single();
    if (error && error.code !== 'PGRST116') throw error;
    return data?.password_ct || null;
};

export const setMasterPasswordHash = async (hash: string): Promise<void> => {
    const targetId = await getVaultOwnerId();
    const { data: existing } = await supabase.from('passwords').select('id').eq('user_id', targetId).eq('service', 'MASTER').single();
    if (existing) await supabase.from('passwords').update({ password_ct: hash }).eq('id', existing.id);
    else await supabase.from('passwords').insert({ user_id: targetId, service: 'MASTER', username: 'SYSTEM', password_ct: hash });
};

export const addContentItem = async (content: Omit<Content, 'id'>): Promise<Content> => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.user) throw new Error('User not authenticated.');
    const { data, error = { message: 'Unknown error' } as any } = await supabase.from('content').insert({ user_id: session.user.id, title: content.title, type: content.type, data: content.data }).select().single();
    if (error) throw error;
    return data as Content;
};

const LIVE_WHITEBOARD_TABLE = 'whiteboard_items_live';
export const getWhiteboardItems = async (): Promise<WhiteboardItemOld[]> => {
    const { data, error } = await supabase.from(LIVE_WHITEBOARD_TABLE).select('*');
    if (error) throw error;
    return data || [];
};

export const addWhiteboardItem = async (item: Omit<WhiteboardItemOld, 'id' | 'user_id' | 'created_at'>): Promise<WhiteboardItemOld> => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("User not authenticated");
    const { data, error = { message: 'Unknown error' } as any } = await supabase.from(LIVE_WHITEBOARD_TABLE).insert({ ...item, user_id: user.id }).select().single();
    if (error) throw error;
    return data;
};

export const updateWhiteboardItem = async (item: WhiteboardItemOld): Promise<WhiteboardItemOld> => {
    const { id, ...itemData } = item;
    const { data, error = { message: 'Unknown error' } as any } = await supabase.from(LIVE_WHITEBOARD_TABLE).update(itemData).eq('id', id).select().single();
    if (error) throw error;
    return data;
};

export const deleteLiveWhiteboardItem = async (id: string): Promise<void> => {
    const { error = { message: 'Unknown error' } as any } = await supabase.from(LIVE_WHITEBOARD_TABLE).delete().eq('id', id);
    if (error) throw error;
};

export const subscribeToLiveWhiteboardItems = (onInsert: (newItem: WhiteboardItemOld) => void, onUpdate: (updatedItem: WhiteboardItemOld) => void, onDelete: (deletedId: string) => void): RealtimeChannel => {
    const channel = supabase.channel('live-whiteboard-items');
    channel.on<WhiteboardItemOld>('postgres_changes', { event: 'INSERT', schema: 'public', table: LIVE_WHITEBOARD_TABLE }, (payload) => onInsert(payload.new))
           .on<WhiteboardItemOld>('postgres_changes', { event: 'UPDATE', schema: 'public', table: LIVE_WHITEBOARD_TABLE }, (payload) => onUpdate(payload.new))
           .on<{ id: string }>('postgres_changes', { event: 'DELETE', schema: 'public', table: LIVE_WHITEBOARD_TABLE }, (payload) => onDelete(payload.old.id))
           .subscribe();
    return channel;
};

export const uploadFile = async (file: File): Promise<void> => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error('User not authenticated');
    const filePath = `${user.id}/UPLOADS/${uuidv4()}-${sanitizeFileName(file.name)}`;
    const { error: uploadError } = await supabase.storage.from('user_files').upload(filePath, file);
    if (uploadError) throw uploadError;
};

import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { GoogleGenAI } from '@google/genai';
import { Project, ProjectTask, IshikawaDiagramData, Document } from '../types';

interface ReportData {
    project: Project;
    tasks: ProjectTask[];
    documents: Document[];
    ishikawa?: IshikawaDiagramData | null;
}

export const generateCorporateReport = async (data: ReportData, apiKey: string) => {
    const { project, tasks, documents, ishikawa } = data;
    const ai = new GoogleGenAI({ apiKey });

    // 1. Preparar contexto para la IA
    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.status === 'completed');
    const failedTasks = tasks.filter(t => t.status === 'failed');
    const pendingTasks = tasks.filter(t => t.status === 'pending');
    const progress = totalTasks > 0 ? Math.round((completedTasks.length / totalTasks) * 100) : 0;

    const contextPrompt = `
        Genera el contenido textual para un REPORTE CORPORATIVO DE PROYECTO con redacción formal y profesional en tercera persona.
        PROYECTO: "${project.name}"
        OBJETIVO ORIGINAL: "${project.objective}"
        DATOS DE EJECUCIÓN:
        - Avance Real: ${progress}%
        - Tareas Totales: ${totalTasks}
        - Tareas Exitosas: ${completedTasks.length}
        - Tareas Fallidas: ${failedTasks.length}
        - Comentarios de fallas: ${failedTasks.map(t => t.comments || 'Sin comentarios').join('; ')}
        - Ishikawa disponible: ${!!ishikawa ? 'Sí' : 'No'}

        NECESITO QUE REDACTES 2 SECCIONES CLAVE:
        1. RESUMEN EJECUTIVO: Una síntesis de alto nivel que explique el propósito estratégico, el desempeño y el valor aportado. (Máximo 250 palabras).
        2. ANÁLISIS DE RIESGOS E INCIDENCIAS: Basado en las tareas fallidas, redacta un análisis profesional de los puntos críticos y el impacto en el cronograma. Si no hay fallas, indica que el control de riesgos ha sido óptimo.

        Devuelve el resultado en formato JSON con llaves "executiveSummary" y "riskAnalysis". No uses lenguaje técnico de programación ni menciones a la IA.
    `;

    let aiContent = { 
        executiveSummary: project.executiveSummary || 'No se registró un resumen ejecutivo para este periodo.', 
        riskAnalysis: 'No se registraron incidencias críticas en el periodo reportado.' 
    };

    try {
        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: contextPrompt,
            config: { responseMimeType: "application/json" }
        });
        const parsed = JSON.parse(result.text);
        // Si el usuario ya escribió algo, respetamos su texto o lo usamos como base
        aiContent.executiveSummary = project.executiveSummary || parsed.executiveSummary;
        aiContent.riskAnalysis = parsed.riskAnalysis;
    } catch (e) {
        console.warn("Gemini Synthesis failed, using defaults", e);
    }

    // 2. Construir PDF
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' }) as any;
    const margin = 20;
    const pageWidth = doc.internal.pageSize.getWidth();

    // --- PÁGINA 1: PORTADA ---
    doc.setFillColor(7, 11, 20); // Azul muy oscuro (estilo Nexus)
    doc.rect(0, 0, pageWidth, 40, 'F');

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(74, 144, 226);
    doc.text('REPORTE CORPORATIVO DE PROYECTO', margin, 25);
    doc.text('UAD SYSTEM v2.5', pageWidth - margin - 35, 25);

    doc.setTextColor(0, 0, 0);
    doc.setFontSize(28);
    doc.text(project.name.toUpperCase(), margin, 80, { maxWidth: pageWidth - 40 });

    doc.setDrawColor(74, 144, 226);
    doc.setLineWidth(1);
    doc.line(margin, 85, margin + 50, 85);

    doc.setFontSize(12);
    doc.setFont('helvetica', 'normal');
    doc.text(`Responsable del Proyecto:`, margin, 110);
    doc.setFont('helvetica', 'bold');
    doc.text(project.leader || 'No asignado', margin + 55, 110);

    doc.setFont('helvetica', 'normal');
    doc.text(`Área Solicitante:`, margin, 120);
    doc.setFont('helvetica', 'bold');
    doc.text('Mejora Continua / Calidad', margin + 55, 120);

    doc.setFont('helvetica', 'normal');
    doc.text(`Estado Actual:`, margin, 130);
    doc.setFont('helvetica', 'bold');
    doc.text(project.status.toUpperCase(), margin + 55, 130);

    doc.setFont('helvetica', 'normal');
    doc.text(`Cronograma:`, margin, 140);
    doc.setFont('helvetica', 'bold');
    doc.text(`${project.startDate} a ${project.endDate || 'Presente'}`, margin + 55, 140);

    // Footer Portada
    doc.setFont('helvetica', 'italic');
    doc.setFontSize(10);
    doc.setTextColor(100, 100, 100);
    doc.text('Suave y Facil S.A. de C.V.', pageWidth / 2, 270, { align: 'center' });
    doc.text('Documento Confidencial - Propiedad Institucional', pageWidth / 2, 275, { align: 'center' });

    // --- PÁGINA 2: RESUMEN EJECUTIVO ---
    doc.addPage();
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(40, 40, 40);
    doc.text('1. RESUMEN EJECUTIVO', margin, 30);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.setTextColor(60, 60, 60);
    const splitSummary = doc.splitTextToSize(aiContent.executiveSummary, pageWidth - 40);
    doc.text(splitSummary, margin, 45, { lineHeightFactor: 1.5 });

    // --- SECCIÓN 2: INFORMACIÓN GENERAL ---
    let yPos = 45 + (splitSummary.length * 7) + 15;
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('2. INFORMACIÓN GENERAL DEL PROYECTO', margin, yPos);

    doc.autoTable({
        startY: yPos + 10,
        margin: { left: margin },
        headStyles: { fillColor: [40, 40, 40], textColor: [255, 255, 255] },
        body: [
            ['Objetivo Estratégico', project.objective],
            ['Líder de Proyecto', project.leader],
            ['Equipo de Trabajo', project.team.join(', ')],
            ['Periodo Ejecución', `${project.startDate} al ${project.endDate}`],
            ['Porcentaje de Avance', `${progress}%`]
        ],
        theme: 'grid',
        styles: { fontSize: 10, cellPadding: 4 }
    });

    // --- PÁGINA 3: GESTIÓN DE TAREAS ---
    doc.addPage();
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('3. GESTIÓN DE TAREAS Y EJECUCIÓN', margin, 30);

    const taskRows = tasks.map(t => [
        t.title,
        t.assignedTo || 'N/A',
        t.status === 'completed' ? 'Completado' : t.status === 'failed' ? 'Incidencia' : 'Pendiente',
        t.comments || '-'
    ]);

    doc.autoTable({
        startY: 40,
        margin: { left: margin },
        head: [['Actividad', 'Responsable', 'Estado', 'Observaciones']],
        body: taskRows,
        headStyles: { fillColor: [74, 144, 226] },
        styles: { fontSize: 9 }
    });

    // --- ANÁLISIS DE RIESGOS ---
    yPos = doc.lastAutoTable.finalY + 20;
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('4. ANÁLISIS DE RIESGOS Y PUNTOS CRÍTICOS', margin, yPos);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    const splitRisks = doc.splitTextToSize(aiContent.riskAnalysis, pageWidth - 40);
    doc.text(splitRisks, margin, yPos + 10, { lineHeightFactor: 1.5 });

    // --- ISHIKAWA (SI EXISTE) ---
    if (ishikawa) {
        doc.addPage();
        doc.setFontSize(16);
        doc.setFont('helvetica', 'bold');
        doc.text('5. ANÁLISIS DE CAUSA RAÍZ (ISHIKAWA 6M)', margin, 30);

        doc.setFont('helvetica', 'normal');
        doc.setFontSize(10);
        doc.text('A continuación se detallan las causas identificadas durante el análisis técnico de calidad:', margin, 40);

        const categories = [
            { id: 'method', label: 'Métodos' },
            { id: 'machine', label: 'Maquinaria' },
            { id: 'material', label: 'Materiales' },
            { id: 'manpower', label: 'Mano de Obra' },
            { id: 'measurement', label: 'Medición' },
            { id: 'environment', label: 'Medio Ambiente' },
        ];

        const ishikawaRows = categories.map(cat => [
            cat.label,
            ishikawa.causes[cat.id]?.join(', ') || 'Sin hallazgos registrados'
        ]);

        doc.autoTable({
            startY: 50,
            margin: { left: margin },
            head: [['Categoría 6M', 'Causas Identificadas']],
            body: ishikawaRows,
            headStyles: { fillColor: [100, 100, 100] }
        });
    }

    // --- CIERRE ---
    doc.addPage();
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('6. RESULTADOS Y CIERRE', margin, 30);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    const splitConclusions = doc.splitTextToSize(project.finalConclusions || 'Se determina que el proyecto continúa en su fase operativa bajo supervisión del departamento de Calidad.', pageWidth - 40);
    doc.text(splitConclusions, margin, 45, { lineHeightFactor: 1.5 });

    // Firmas
    const signY = 200;
    doc.setDrawColor(200, 200, 200);
    doc.line(margin, signY, margin + 60, signY);
    doc.line(pageWidth - margin - 60, signY, pageWidth - margin, signY);

    doc.setFontSize(9);
    doc.text('Líder de Proyecto', margin + 30, signY + 5, { align: 'center' });
    doc.text('Dirección General', pageWidth - margin - 30, signY + 5, { align: 'center' });

    doc.save(`REPORTE_PROYECTO_${project.name.replace(/\s+/g, '_')}_${Date.now()}.pdf`);
};

import React, { useState, useEffect, useMemo } from 'react';
import { Project, ProjectTask, ProjectStatus, Document, Folder, UserPermissions, User } from '../../types';
import { ArrowLeftIcon, TrashIcon, PencilAltIcon, SparklesIcon, DocumentTextIcon, RefreshIcon } from '../Icons';
import ConfirmationModal from './ConfirmationModal';
import ProjectTasksTab from './ProjectTasksTab';
import ProjectDocumentsTab from './ProjectDocumentsTab';
import GanttChart from './GanttChart';
import IshikawaDiagram from './IshikawaDiagram';
import { generateCorporateReport } from '../../services/reportService';
import { getIshikawaDiagram, getGeminiApiKey } from '../../services/supabaseService';
import Spinner from '../Spinner';

interface ProjectDetailViewProps {
  project: Project;
  tasks: ProjectTask[];
  documents: Document[];
  folders: Folder[];
  onBackToList: () => void;
  onDeleteProject: (id: string) => void;
  onSaveProject: (project: Project) => void;
  onAddTask: (projectId: string, details: { title: string; startDate: string; duration: number; assignedTo: string }, parentId?: string | null) => void;
  onToggleTask: (id: string) => void;
  onUpdateTask: (task: ProjectTask) => void;
  onDeleteTask: (id: string) => void;
  onAddDocument: (file: File, folderId: string, projectId: string | null) => Promise<void>;
  onDeleteDocument: (doc: Document) => Promise<void>;
  userPermissions: UserPermissions | null;
  user: User;
}

const ProjectDetailView: React.FC<ProjectDetailViewProps> = (props) => {
  const { 
      project, tasks, documents, folders, onBackToList, onDeleteProject, 
      onSaveProject, onAddTask, onToggleTask, onUpdateTask, onDeleteTask,
      onAddDocument, onDeleteDocument, userPermissions, user
  } = props;
  const [activeTab, setActiveTab] = useState('Resumen');
  const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);
  const [isIshikawaConfirmOpen, setIsIshikawaConfirmOpen] = useState(false);
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);

  // --- Inline editing state ---
  const [isEditing, setIsEditing] = useState(false);
  const [editableProject, setEditableProject] = useState<Project>(project);

  useEffect(() => {
    setEditableProject(project);
    setIsEditing(false); 
  }, [project]);

  const tabs = useMemo(() => {
      const baseTabs = ['Resumen', 'Tareas', 'Documentos', 'Gantt'];
      if (project.ishikawaEnabled) {
          baseTabs.push('Ishikawa');
      }
      return baseTabs;
  }, [project.ishikawaEnabled]);

  const projectDocuments = useMemo(() => documents.filter(doc => doc.projectId === project.id), [documents, project.id]);

  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(t => t.status === 'completed').length;
  const progress = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

  const handleDeleteConfirm = () => {
    onDeleteProject(project.id);
    setDeleteModalOpen(false);
  };

  const handleToggleIshikawa = () => {
      const updatedProject = { ...project, ishikawaEnabled: !project.ishikawaEnabled };
      onSaveProject(updatedProject);
      setIsIshikawaConfirmOpen(false);
      if (!updatedProject.ishikawaEnabled && activeTab === 'Ishikawa') {
          setActiveTab('Resumen');
      }
  };

  const handleGenerateReport = async () => {
      setIsGeneratingReport(true);
      try {
          const apiKey = await getGeminiApiKey();
          const ishikawaData = project.ishikawaEnabled ? await getIshikawaDiagram(project.id) : null;

          await generateCorporateReport({
              project,
              tasks,
              documents: projectDocuments,
              ishikawa: ishikawaData
          }, apiKey);

      } catch (error) {
          console.error("Report Generation Error:", error);
          alert("Error al generar el reporte corporativo.");
      } finally {
          setIsGeneratingReport(false);
      }
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setEditableProject(prev => ({ ...prev, [name]: value }));
  };

  const handleSave = () => {
    onSaveProject(editableProject);
    setIsEditing(false);
  };

  const handleCancel = () => {
    setEditableProject(project); 
    setIsEditing(false);
  };

  const canEditProject = userPermissions?.proyectos?.canEdit ?? false;
  const canDeleteProject = userPermissions?.proyectos?.canDelete ?? false;
  const canManageTasks = userPermissions?.proyectos?.canManageTasks ?? false;

  const renderActiveTabContent = () => {
    switch (activeTab) {
      case 'Tareas':
        return <ProjectTasksTab 
                  project={project}
                  tasks={tasks} 
                  onAddTask={(details, parentId) => onAddTask(project.id, details, parentId)}
                  onToggleTask={onToggleTask}
                  onUpdateTask={onUpdateTask}
                  onDeleteTask={onDeleteTask}
                  isEditor={canManageTasks}
                />;
      case 'Resumen':
        return (
          <div className="space-y-6">
            <div className="space-y-4 bg-light-card dark:bg-dark-card p-6 rounded-lg border border-light-border dark:border-dark-border">
              <div className="flex justify-between items-center mb-2">
                  <h3 className="text-lg font-bold">Información del Proyecto</h3>
                  <div className="flex items-center gap-3">
                      <button 
                        onClick={handleGenerateReport}
                        disabled={isGeneratingReport}
                        className={`flex items-center text-xs font-bold uppercase tracking-widest px-4 py-2 rounded bg-slate-900 dark:bg-slate-800 text-cyan-400 border border-cyan-500/30 hover:border-cyan-500 hover:shadow-[0_0_10px_rgba(6,182,212,0.3)] transition-all disabled:opacity-50`}
                      >
                        {isGeneratingReport ? <Spinner size="sm" /> : <DocumentTextIcon className="h-4 w-4 mr-2" />}
                        {isGeneratingReport ? 'Procesando...' : 'REPORTE CORPORATIVO'}
                      </button>

                      {canEditProject && (
                        <button 
                            onClick={() => setIsIshikawaConfirmOpen(true)}
                            className={`flex items-center text-xs font-bold uppercase tracking-wider px-3 py-1.5 rounded-full border transition-all ${project.ishikawaEnabled ? 'bg-brand-primary/10 border-brand-primary text-brand-primary' : 'bg-gray-100 dark:bg-gray-800 border-gray-300 dark:border-gray-600 text-gray-500'}`}
                        >
                            <SparklesIcon className="h-3 w-3 mr-1.5" />
                            Ishikawa: {project.ishikawaEnabled ? 'ON' : 'OFF'}
                        </button>
                      )}
                      {canEditProject && !isEditing && (
                          <button 
                              onClick={() => setIsEditing(true)}
                              className="flex items-center text-sm font-medium text-brand-primary hover:text-brand-secondary"
                          >
                              <PencilAltIcon className="h-4 w-4 mr-1" />
                              Editar
                          </button>
                      )}
                  </div>
              </div>

              {isEditing && canEditProject ? (
                  <div className="space-y-4">
                      <div>
                          <label className="text-sm font-medium">Objetivo del Proyecto</label>
                          <textarea name="objective" rows={2} value={editableProject.objective} onChange={handleEditChange} className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent"/>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div>
                            <label className="text-sm font-medium block">Resumen Ejecutivo (Para Reporte)</label>
                            <textarea name="executiveSummary" rows={4} value={editableProject.executiveSummary} onChange={handleEditChange} placeholder="Define el propósito estratégico para la Dirección..." className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent text-sm"/>
                          </div>
                          <div>
                            <label className="text-sm font-medium block">Conclusiones Finales (Para Reporte)</label>
                            <textarea name="finalConclusions" rows={4} value={editableProject.finalConclusions} onChange={handleEditChange} placeholder="Indica los resultados obtenidos y próximos pasos..." className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent text-sm"/>
                          </div>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-2">
                        <div>
                            <label className="text-sm font-medium">Líder del Proyecto</label>
                            <input type="text" name="leader" value={editableProject.leader} onChange={handleEditChange} className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent"/>
                        </div>
                        <div>
                            <label className="text-sm font-medium">Fecha de Inicio</label>
                            <input type="date" name="startDate" value={editableProject.startDate} onChange={handleEditChange} className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent"/>
                        </div>
                        <div>
                            <label className="text-sm font-medium">Fecha de Fin</label>
                            <input type="date" name="endDate" value={editableProject.endDate} onChange={handleEditChange} className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent"/>
                        </div>
                      </div>
                      <div className="flex justify-end space-x-3 pt-4">
                          <button type="button" onClick={handleCancel} className="px-4 py-2 text-sm font-medium rounded-md border border-light-border dark:border-dark-border hover:bg-gray-100 dark:hover:bg-dark-border">Cancelar</button>
                          <button type="button" onClick={handleSave} className="px-4 py-2 text-sm font-medium rounded-md text-white bg-brand-primary hover:bg-brand-secondary">Guardar Cambios</button>
                      </div>
                  </div>
              ) : (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  <div className="lg:col-span-2 space-y-4">
                      <div>
                          <h4 className="text-xs font-black text-brand-primary uppercase tracking-widest mb-1">Objetivo del Proyecto</h4>
                          <p className="text-light-text-secondary dark:text-dark-text-secondary whitespace-pre-wrap leading-relaxed">{project.objective}</p>
                      </div>
                      {project.executiveSummary && (
                          <div>
                              <h4 className="text-xs font-black text-brand-primary uppercase tracking-widest mb-1">Resumen Ejecutivo</h4>
                              <p className="text-sm text-light-text-secondary dark:text-dark-text-secondary italic leading-relaxed">"{project.executiveSummary}"</p>
                          </div>
                      )}
                  </div>
                  <div className="space-y-4 lg:border-l lg:pl-6 border-light-border dark:border-dark-border">
                      <h4 className="text-base font-bold mb-2">Detalles Operativos</h4>
                      <div>
                          <p className="text-xs font-semibold text-light-text-secondary dark:text-dark-text-secondary uppercase tracking-wider">Estado</p>
                          <p className="font-medium">{project.status}</p>
                      </div>
                      <div>
                          <p className="text-xs font-semibold text-light-text-secondary dark:text-dark-text-secondary uppercase tracking-wider">Líder</p>
                          <p className="font-medium">{project.leader || 'No asignado'}</p>
                      </div>
                      <div>
                          <p className="text-xs font-semibold text-light-text-secondary dark:text-dark-text-secondary uppercase tracking-wider">Periodo</p>
                          <p className="font-medium text-sm">{new Date(project.startDate).toLocaleDateString()} - {project.endDate ? new Date(project.endDate).toLocaleDateString() : 'Activo'}</p>
                      </div>
                  </div>
                </div>
              )}
            </div>

            <div className="bg-light-card dark:bg-dark-card p-6 rounded-lg border border-light-border dark:border-dark-border relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10">
                    <RefreshIcon className="h-24 w-24 animate-spin-slow" />
                </div>
                <h3 className="text-lg font-bold mb-2">Sincronización de Avance Real ({progress}%)</h3>
                <div className="w-full bg-light-bg dark:bg-dark-bg rounded-full h-4 border border-light-border dark:border-dark-border">
                  <div className="bg-brand-primary h-full rounded-full transition-all duration-1000 shadow-[0_0_10px_rgba(74,144,226,0.4)]" style={{ width: `${progress}%` }}></div>
                </div>
                <div className="mt-4 flex flex-wrap gap-4 text-[10px] font-black uppercase tracking-tighter">
                   <div className="flex items-center gap-1 bg-green-500/10 text-green-600 px-2 py-1 rounded">
                       <span className="w-2 h-2 rounded-full bg-green-500"></span>
                       {tasks.filter(t => t.status === 'completed').length} Completadas
                   </div>
                   <div className="flex items-center gap-1 bg-red-500/10 text-red-600 px-2 py-1 rounded">
                        <span className="w-2 h-2 rounded-full bg-red-500"></span>
                        {tasks.filter(t => t.status === 'failed').length} Incidencias
                   </div>
                   <div className="flex items-center gap-1 bg-gray-500/10 text-gray-500 px-2 py-1 rounded">
                        <span className="w-2 h-2 rounded-full bg-gray-500"></span>
                        {tasks.filter(t => t.status === 'pending').length} Pendientes
                   </div>
                </div>
            </div>
          </div>
        );
      case 'Documentos':
             return <ProjectDocumentsTab 
                        project={project} 
                        documents={projectDocuments} 
                        folders={folders} 
                        onAddDocument={onAddDocument} 
                        onDeleteDocument={onDeleteDocument}
                        userPermissions={userPermissions}
                        user={user}
                    />;
      case 'Gantt':
             return (
               <div className="bg-light-card dark:bg-dark-card rounded-lg border border-light-border dark:border-dark-border w-full">
                 <h3 className="text-xl font-bold p-4 pb-2">Diagrama de Gantt del Proyecto</h3>
                 <div className="overflow-x-auto p-4 gantt-scrollbar">
                    <GanttChart project={project} tasks={tasks} />
                 </div>
               </div>
             );
      case 'Ishikawa':
            return <IshikawaDiagram project={project} />;
      default:
        return null;
    }
  };

  return (
    <>
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div>
            <button onClick={onBackToList} className="flex items-center text-sm font-medium text-light-text-secondary dark:text-dark-text-secondary hover:text-brand-primary dark:hover:text-brand-accent mb-2 transition-colors">
                <ArrowLeftIcon className="h-4 w-4 mr-2" />
                Volver a Proyectos
            </button>
            <h1 className="text-3xl font-bold tracking-tight">{project.name}</h1>
            <p className="text-light-text-secondary dark:text-dark-text-secondary mt-1">{project.description}</p>
        </div>
        {canDeleteProject && (
            <button onClick={() => setDeleteModalOpen(true)} className="flex items-center px-4 py-2 text-sm font-medium rounded-md text-red-600 dark:text-red-400 bg-red-500/10 hover:bg-red-500/20 transition-colors">
                <TrashIcon className="h-5 w-5 mr-2" />
                Eliminar
            </button>
        )}
      </div>

      <div className="border-b border-light-border dark:border-dark-border mb-6">
        <nav className="-mb-px flex space-x-6">
          {tabs.map(tab => (
            <button 
              key={tab} 
              onClick={() => setActiveTab(tab)}
              className={`whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm transition-all duration-200 ${activeTab === tab ? 'border-brand-primary text-brand-primary' : 'border-transparent text-light-text-secondary dark:text-dark-text-secondary hover:text-light-text dark:hover:text-dark-text'}`}
            >
              {tab}
            </button>
          ))}
        </nav>
      </div>

      <div className="overflow-hidden">
        {renderActiveTabContent()}
      </div>

      <ConfirmationModal
        isOpen={isDeleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        onConfirm={handleDeleteConfirm}
        title="Eliminar Proyecto"
        message={`¿Estás seguro de que quieres eliminar el proyecto "${project.name}"? Esta acción no se puede deshacer y borrará toda la información relacionada.`}
      />

      <ConfirmationModal
        isOpen={isIshikawaConfirmOpen}
        onClose={() => setIsIshikawaConfirmOpen(false)}
        onConfirm={handleToggleIshikawa}
        title={project.ishikawaEnabled ? "Deshabilitar Ishikawa" : "Habilitar Ishikawa"}
        message={`¿Estás seguro de que quieres ${project.ishikawaEnabled ? 'deshabilitar' : 'habilitar'} la sección de Ishikawa para este proyecto?`}
      />
    </>
  );
};

export default ProjectDetailView;

import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { GoogleGenAI } from '@google/genai';
import { Project, ProjectTask, IshikawaDiagramData, Document } from '../types';

interface ReportData {
    project: Project;
    tasks: ProjectTask[];
    documents: Document[];
    ishikawa?: IshikawaDiagramData | null;
}

export const generateCorporateReport = async (data: ReportData, apiKey: string): Promise<jsPDF> => {
    const { project, tasks, documents, ishikawa } = data;
    const ai = new GoogleGenAI({ apiKey });

    // 1. Preparar contexto para la IA
    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.status === 'completed');
    const failedTasks = tasks.filter(t => t.status === 'failed');
    const pendingTasks = tasks.filter(t => t.status === 'pending');
    const progress = totalTasks > 0 ? Math.round((completedTasks.length / totalTasks) * 100) : 0;

    const contextPrompt = `
        Genera el contenido textual para un REPORTE CORPORATIVO DE PROYECTO con redacción formal y profesional en tercera persona.
        PROYECTO: "${project.name}"
        OBJETIVO ORIGINAL: "${project.objective}"
        DATOS DE EJECUCIÓN:
        - Avance Real: ${progress}%
        - Tareas Totales: ${totalTasks}
        - Tareas Exitosas: ${completedTasks.length}
        - Tareas Fallidas: ${failedTasks.length}
        - Comentarios de fallas: ${failedTasks.map(t => t.comments || 'Sin comentarios').join('; ')}
        - Ishikawa disponible: ${!!ishikawa ? 'Sí' : 'No'}

        NECESITO QUE REDACTES 2 SECCIONES CLAVE:
        1. RESUMEN EJECUTIVO: Una síntesis de alto nivel que explique el propósito estratégico, el desempeño y el valor aportado. (Máximo 250 palabras).
        2. ANÁLISIS DE RIESGOS E INCIDENCIAS: Basado en las tareas fallidas, redacta un análisis profesional de los puntos críticos y el impacto en el cronograma. Si no hay fallas, indica que el control de riesgos ha sido óptimo.

        Devuelve el resultado en formato JSON con llaves "executiveSummary" y "riskAnalysis". No uses lenguaje técnico de programación ni menciones a la IA.
    `;

    let aiContent = { 
        executiveSummary: project.executiveSummary || 'No se registró un resumen ejecutivo para este periodo.', 
        riskAnalysis: 'No se registraron incidencias críticas en el periodo reportado.' 
    };

    try {
        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: contextPrompt,
            config: { responseMimeType: "application/json" }
        });
        const parsed = JSON.parse(result.text);
        aiContent.executiveSummary = project.executiveSummary || parsed.executiveSummary;
        aiContent.riskAnalysis = parsed.riskAnalysis;
    } catch (e) {
        console.warn("Gemini Synthesis failed, using defaults", e);
    }

    // 2. Construir PDF
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' }) as any;
    const margin = 20;
    const pageWidth = doc.internal.pageSize.getWidth();

    // --- PÁGINA 1: PORTADA ---
    doc.setFillColor(7, 11, 20); 
    doc.rect(0, 0, pageWidth, 40, 'F');

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(74, 144, 226);
    doc.text('REPORTE CORPORATIVO DE PROYECTO', margin, 25);
    doc.text('UAD SYSTEM v2.5', pageWidth - margin - 35, 25);

    doc.setTextColor(0, 0, 0);
    doc.setFontSize(28);
    doc.text(project.name.toUpperCase(), margin, 80, { maxWidth: pageWidth - 40 });

    doc.setDrawColor(74, 144, 226);
    doc.setLineWidth(1);
    doc.line(margin, 85, margin + 50, 85);

    doc.setFontSize(12);
    doc.setFont('helvetica', 'normal');
    doc.text(`Responsable del Proyecto:`, margin, 110);
    doc.setFont('helvetica', 'bold');
    doc.text(project.leader || 'No asignado', margin + 55, 110);

    doc.setFont('helvetica', 'normal');
    doc.text(`Área Solicitante:`, margin, 120);
    doc.setFont('helvetica', 'bold');
    doc.text('Mejora Continua / Calidad', margin + 55, 120);

    doc.setFont('helvetica', 'normal');
    doc.text(`Estado Actual:`, margin, 130);
    doc.setFont('helvetica', 'bold');
    doc.text(project.status.toUpperCase(), margin + 55, 130);

    doc.setFont('helvetica', 'normal');
    doc.text(`Cronograma:`, margin, 140);
    doc.setFont('helvetica', 'bold');
    doc.text(`${project.startDate} a ${project.endDate || 'Presente'}`, margin + 55, 140);

    doc.setFont('helvetica', 'italic');
    doc.setFontSize(10);
    doc.setTextColor(100, 100, 100);
    doc.text('Suave y Facil S.A. de C.V.', pageWidth / 2, 270, { align: 'center' });
    doc.text('Documento Confidencial - Propiedad Institucional', pageWidth / 2, 275, { align: 'center' });

    // --- PÁGINA 2: RESUMEN EJECUTIVO ---
    doc.addPage();
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(40, 40, 40);
    doc.text('1. RESUMEN EJECUTIVO', margin, 30);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.setTextColor(60, 60, 60);
    const splitSummary = doc.splitTextToSize(aiContent.executiveSummary, pageWidth - 40);
    doc.text(splitSummary, margin, 45, { lineHeightFactor: 1.5 });

    let yPos = 45 + (splitSummary.length * 7) + 15;
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('2. INFORMACIÓN GENERAL DEL PROYECTO', margin, yPos);

    doc.autoTable({
        startY: yPos + 10,
        margin: { left: margin },
        headStyles: { fillColor: [40, 40, 40], textColor: [255, 255, 255] },
        body: [
            ['Objetivo Estratégico', project.objective],
            ['Líder de Proyecto', project.leader],
            ['Equipo de Trabajo', project.team.join(', ')],
            ['Periodo Ejecución', `${project.startDate} al ${project.endDate}`],
            ['Porcentaje de Avance', `${progress}%`]
        ],
        theme: 'grid',
        styles: { fontSize: 10, cellPadding: 4 }
    });

    // --- PÁGINA 3: GESTIÓN DE TAREAS ---
    doc.addPage();
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('3. GESTIÓN DE TAREAS Y EJECUCIÓN', margin, 30);

    const taskRows = tasks.map(t => [
        t.title,
        t.assignedTo || 'N/A',
        t.status === 'completed' ? 'Completado' : t.status === 'failed' ? 'Incidencia' : 'Pendiente',
        t.comments || '-'
    ]);

    doc.autoTable({
        startY: 40,
        margin: { left: margin },
        head: [['Actividad', 'Responsable', 'Estado', 'Observaciones']],
        body: taskRows,
        headStyles: { fillColor: [74, 144, 226] },
        styles: { fontSize: 9 }
    });

    yPos = doc.lastAutoTable.finalY + 20;
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('4. ANÁLISIS DE RIESGOS Y PUNTOS CRÍTICOS', margin, yPos);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    const splitRisks = doc.splitTextToSize(aiContent.riskAnalysis, pageWidth - 40);
    doc.text(splitRisks, margin, yPos + 10, { lineHeightFactor: 1.5 });

    if (ishikawa) {
        doc.addPage();
        doc.setFontSize(16);
        doc.setFont('helvetica', 'bold');
        doc.text('5. ANÁLISIS DE CAUSA RAÍZ (ISHIKAWA 6M)', margin, 30);

        doc.setFont('helvetica', 'normal');
        doc.setFontSize(10);
        doc.text('A continuación se detallan las causas identificadas durante el análisis técnico de calidad:', margin, 40);

        const categories = [
            { id: 'method', label: 'Métodos' },
            { id: 'machine', label: 'Maquinaria' },
            { id: 'material', label: 'Materiales' },
            { id: 'manpower', label: 'Mano de Obra' },
            { id: 'measurement', label: 'Medición' },
            { id: 'environment', label: 'Medio Ambiente' },
        ];

        const ishikawaRows = categories.map(cat => [
            cat.label,
            ishikawa.causes[cat.id]?.join(', ') || 'Sin hallazgos registrados'
        ]);

        doc.autoTable({
            startY: 50,
            margin: { left: margin },
            head: [['Categoría 6M', 'Causas Identificadas']],
            body: ishikawaRows,
            headStyles: { fillColor: [100, 100, 100] }
        });
    }

    doc.addPage();
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('6. RESULTADOS Y CIERRE', margin, 30);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    const splitConclusions = doc.splitTextToSize(project.finalConclusions || 'Se determina que el proyecto continúa en su fase operativa bajo supervisión del departamento de Calidad.', pageWidth - 40);
    doc.text(splitConclusions, margin, 45, { lineHeightFactor: 1.5 });

    const signY = 200;
    doc.setDrawColor(200, 200, 200);
    doc.line(margin, signY, margin + 60, signY);
    doc.line(pageWidth - margin - 60, signY, pageWidth - margin, signY);

    doc.setFontSize(9);
    doc.text('Líder de Proyecto', margin + 30, signY + 5, { align: 'center' });
    doc.text('Dirección General', pageWidth - margin - 30, signY + 5, { align: 'center' });

    return doc;
};

import React, { useState, useEffect, useMemo } from 'react';
import { Project, ProjectTask, ProjectStatus, Document, Folder, UserPermissions, User } from '../../types';
import { ArrowLeftIcon, TrashIcon, PencilAltIcon, SparklesIcon, DocumentTextIcon, RefreshIcon, XIcon, DocumentDownloadIcon } from '../Icons';
import ConfirmationModal from './ConfirmationModal';
import ProjectTasksTab from './ProjectTasksTab';
import ProjectDocumentsTab from './ProjectDocumentsTab';
import GanttChart from './GanttChart';
import IshikawaDiagram from './IshikawaDiagram';
import { generateCorporateReport } from '../../services/reportService';
import { getIshikawaDiagram, getGeminiApiKey } from '../../services/supabaseService';
import Spinner from '../Spinner';

interface ProjectDetailViewProps {
  project: Project;
  tasks: ProjectTask[];
  documents: Document[];
  folders: Folder[];
  onBackToList: () => void;
  onDeleteProject: (id: string) => void;
  onSaveProject: (project: Project) => void;
  onAddTask: (projectId: string, details: { title: string; startDate: string; duration: number; assignedTo: string }, parentId?: string | null) => void;
  onToggleTask: (id: string) => void;
  onUpdateTask: (task: ProjectTask) => void;
  onDeleteTask: (id: string) => void;
  onAddDocument: (file: File, folderId: string, projectId: string | null) => Promise<void>;
  onDeleteDocument: (doc: Document) => Promise<void>;
  userPermissions: UserPermissions | null;
  user: User;
}

const ProjectDetailView: React.FC<ProjectDetailViewProps> = (props) => {
  const { 
      project, tasks, documents, folders, onBackToList, onDeleteProject, 
      onSaveProject, onAddTask, onToggleTask, onUpdateTask, onDeleteTask,
      onAddDocument, onDeleteDocument, userPermissions, user
  } = props;
  const [activeTab, setActiveTab] = useState('Resumen');
  const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);
  const [isIshikawaConfirmOpen, setIsIshikawaConfirmOpen] = useState(false);
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);

  // --- Report Preview State ---
  const [previewPdfUrl, setPreviewPdfUrl] = useState<string | null>(null);
  const [reportDoc, setReportDoc] = useState<any>(null);

  const [isEditing, setIsEditing] = useState(false);
  const [editableProject, setEditableProject] = useState<Project>(project);

  useEffect(() => {
    setEditableProject(project);
    setIsEditing(false); 
  }, [project]);

  const tabs = useMemo(() => {
      const baseTabs = ['Resumen', 'Tareas', 'Documentos', 'Gantt'];
      if (project.ishikawaEnabled) {
          baseTabs.push('Ishikawa');
      }
      return baseTabs;
  }, [project.ishikawaEnabled]);

  const projectDocuments = useMemo(() => documents.filter(doc => doc.projectId === project.id), [documents, project.id]);

  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(t => t.status === 'completed').length;
  const progress = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

  const handleDeleteConfirm = () => {
    onDeleteProject(project.id);
    setDeleteModalOpen(false);
  };

  const handleToggleIshikawa = () => {
      const updatedProject = { ...project, ishikawaEnabled: !project.ishikawaEnabled };
      onSaveProject(updatedProject);
      setIsIshikawaConfirmOpen(false);
      if (!updatedProject.ishikawaEnabled && activeTab === 'Ishikawa') {
          setActiveTab('Resumen');
      }
  };

  const handleGenerateReport = async () => {
      setIsGeneratingReport(true);
      try {
          const apiKey = await getGeminiApiKey();
          const ishikawaData = project.ishikawaEnabled ? await getIshikawaDiagram(project.id) : null;

          const doc = await generateCorporateReport({
              project,
              tasks,
              documents: projectDocuments,
              ishikawa: ishikawaData
          }, apiKey);

          const url = doc.output('bloburl');
          setReportDoc(doc);
          setPreviewPdfUrl(url);

      } catch (error) {
          console.error("Report Generation Error:", error);
          alert("Error al generar el reporte corporativo.");
      } finally {
          setIsGeneratingReport(false);
      }
  };

  const handleDownloadReport = () => {
      if (reportDoc) {
          reportDoc.save(`REPORTE_PROYECTO_${project.name.replace(/\s+/g, '_')}_${Date.now()}.pdf`);
          setPreviewPdfUrl(null);
          setReportDoc(null);
      }
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setEditableProject(prev => ({ ...prev, [name]: value }));
  };

  const handleSave = () => {
    onSaveProject(editableProject);
    setIsEditing(false);
  };

  const handleCancel = () => {
    setEditableProject(project); 
    setIsEditing(false);
  };

  const canEditProject = userPermissions?.proyectos?.canEdit ?? false;
  const canDeleteProject = userPermissions?.proyectos?.canDelete ?? false;
  const canManageTasks = userPermissions?.proyectos?.canManageTasks ?? false;

  const renderActiveTabContent = () => {
    switch (activeTab) {
      case 'Tareas':
        return <ProjectTasksTab 
                  project={project}
                  tasks={tasks} 
                  onAddTask={(details, parentId) => onAddTask(project.id, details, parentId)}
                  onToggleTask={onToggleTask}
                  onUpdateTask={onUpdateTask}
                  onDeleteTask={onDeleteTask}
                  isEditor={canManageTasks}
                />;
      case 'Resumen':
        return (
          <div className="space-y-6">
            <div className="space-y-4 bg-light-card dark:bg-dark-card p-6 rounded-lg border border-light-border dark:border-dark-border">
              <div className="flex justify-between items-center mb-2">
                  <h3 className="text-lg font-bold">Información del Proyecto</h3>
                  <div className="flex items-center gap-3">
                      <button 
                        onClick={handleGenerateReport}
                        disabled={isGeneratingReport}
                        className={`flex items-center text-xs font-bold uppercase tracking-widest px-4 py-2 rounded bg-slate-900 dark:bg-slate-800 text-cyan-400 border border-cyan-500/30 hover:border-cyan-500 hover:shadow-[0_0_10px_rgba(6,182,212,0.3)] transition-all disabled:opacity-50`}
                      >
                        {isGeneratingReport ? <Spinner size="sm" /> : <DocumentTextIcon className="h-4 w-4 mr-2" />}
                        {isGeneratingReport ? 'Procesando...' : 'VISTA PREVIA REPORTE'}
                      </button>

                      {canEditProject && (
                        <button 
                            onClick={() => setIsIshikawaConfirmOpen(true)}
                            className={`flex items-center text-xs font-bold uppercase tracking-wider px-3 py-1.5 rounded-full border transition-all ${project.ishikawaEnabled ? 'bg-brand-primary/10 border-brand-primary text-brand-primary' : 'bg-gray-100 dark:bg-gray-800 border-gray-300 dark:border-gray-600 text-gray-500'}`}
                        >
                            <SparklesIcon className="h-3 w-3 mr-1.5" />
                            Ishikawa: {project.ishikawaEnabled ? 'ON' : 'OFF'}
                        </button>
                      )}
                      {canEditProject && !isEditing && (
                          <button 
                              onClick={() => setIsEditing(true)}
                              className="flex items-center text-sm font-medium text-brand-primary hover:text-brand-secondary"
                          >
                              <PencilAltIcon className="h-4 w-4 mr-1" />
                              Editar
                          </button>
                      )}
                  </div>
              </div>

              {isEditing && canEditProject ? (
                  <div className="space-y-4">
                      <div>
                          <label className="text-sm font-medium">Objetivo del Proyecto</label>
                          <textarea name="objective" rows={2} value={editableProject.objective} onChange={handleEditChange} className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent"/>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div>
                            <label className="text-sm font-medium block">Resumen Ejecutivo (Para Reporte)</label>
                            <textarea name="executiveSummary" rows={4} value={editableProject.executiveSummary} onChange={handleEditChange} placeholder="Define el propósito estratégico para la Dirección..." className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent text-sm"/>
                          </div>
                          <div>
                            <label className="text-sm font-medium block">Conclusiones Finales (Para Reporte)</label>
                            <textarea name="finalConclusions" rows={4} value={editableProject.finalConclusions} onChange={handleEditChange} placeholder="Indica los resultados obtenidos y próximos pasos..." className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent text-sm"/>
                          </div>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-2">
                        <div>
                            <label className="text-sm font-medium">Líder del Proyecto</label>
                            <input type="text" name="leader" value={editableProject.leader} onChange={handleEditChange} className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent"/>
                        </div>
                        <div>
                            <label className="text-sm font-medium">Fecha de Inicio</label>
                            <input type="date" name="startDate" value={editableProject.startDate} onChange={handleEditChange} className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent"/>
                        </div>
                        <div>
                            <label className="text-sm font-medium">Fecha de Fin</label>
                            <input type="date" name="endDate" value={editableProject.endDate} onChange={handleEditChange} className="w-full mt-1 p-2 border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md focus:ring-brand-accent"/>
                        </div>
                      </div>
                      <div className="flex justify-end space-x-3 pt-4">
                          <button type="button" onClick={handleCancel} className="px-4 py-2 text-sm font-medium rounded-md border border-light-border dark:border-dark-border hover:bg-gray-100 dark:hover:bg-dark-border">Cancelar</button>
                          <button type="button" onClick={handleSave} className="px-4 py-2 text-sm font-medium rounded-md text-white bg-brand-primary hover:bg-brand-secondary">Guardar Cambios</button>
                      </div>
                  </div>
              ) : (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  <div className="lg:col-span-2 space-y-4">
                      <div>
                          <h4 className="text-xs font-black text-brand-primary uppercase tracking-widest mb-1">Objetivo del Proyecto</h4>
                          <p className="text-light-text-secondary dark:text-dark-text-secondary whitespace-pre-wrap leading-relaxed">{project.objective}</p>
                      </div>
                      {project.executiveSummary && (
                          <div>
                              <h4 className="text-xs font-black text-brand-primary uppercase tracking-widest mb-1">Resumen Ejecutivo</h4>
                              <p className="text-sm text-light-text-secondary dark:text-dark-text-secondary italic leading-relaxed">"{project.executiveSummary}"</p>
                          </div>
                      )}
                  </div>
                  <div className="space-y-4 lg:border-l lg:pl-6 border-light-border dark:border-dark-border">
                      <h4 className="text-base font-bold mb-2">Detalles Operativos</h4>
                      <div>
                          <p className="text-xs font-semibold text-light-text-secondary dark:text-dark-text-secondary uppercase tracking-wider">Estado</p>
                          <p className="font-medium">{project.status}</p>
                      </div>
                      <div>
                          <p className="text-xs font-semibold text-light-text-secondary dark:text-dark-text-secondary uppercase tracking-wider">Líder</p>
                          <p className="font-medium">{project.leader || 'No asignado'}</p>
                      </div>
                      <div>
                          <p className="text-xs font-semibold text-light-text-secondary dark:text-dark-text-secondary uppercase tracking-wider">Periodo</p>
                          <p className="font-medium text-sm">{new Date(project.startDate).toLocaleDateString()} - {project.endDate ? new Date(project.endDate).toLocaleDateString() : 'Activo'}</p>
                      </div>
                  </div>
                </div>
              )}
            </div>

            <div className="bg-light-card dark:bg-dark-card p-6 rounded-lg border border-light-border dark:border-dark-border relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10">
                    <RefreshIcon className="h-24 w-24 animate-spin-slow" />
                </div>
                <h3 className="text-lg font-bold mb-2">Sincronización de Avance Real ({progress}%)</h3>
                <div className="w-full bg-light-bg dark:bg-dark-bg rounded-full h-4 border border-light-border dark:border-dark-border">
                  <div className="bg-brand-primary h-full rounded-full transition-all duration-1000 shadow-[0_0_10px_rgba(74,144,226,0.4)]" style={{ width: `${progress}%` }}></div>
                </div>
                <div className="mt-4 flex flex-wrap gap-4 text-[10px] font-black uppercase tracking-tighter">
                   <div className="flex items-center gap-1 bg-green-500/10 text-green-600 px-2 py-1 rounded">
                       <span className="w-2 h-2 rounded-full bg-green-500"></span>
                       {tasks.filter(t => t.status === 'completed').length} Completadas
                   </div>
                   <div className="flex items-center gap-1 bg-red-500/10 text-red-600 px-2 py-1 rounded">
                        <span className="w-2 h-2 rounded-full bg-red-500"></span>
                        {tasks.filter(t => t.status === 'failed').length} Incidencias
                   </div>
                   <div className="flex items-center gap-1 bg-gray-500/10 text-gray-500 px-2 py-1 rounded">
                        <span className="w-2 h-2 rounded-full bg-gray-500"></span>
                        {tasks.filter(t => t.status === 'pending').length} Pendientes
                   </div>
                </div>
            </div>
          </div>
        );
      case 'Documentos':
             return <ProjectDocumentsTab 
                        project={project} 
                        documents={projectDocuments} 
                        folders={folders} 
                        onAddDocument={onAddDocument} 
                        onDeleteDocument={onDeleteDocument}
                        userPermissions={userPermissions}
                        user={user}
                    />;
      case 'Gantt':
             return (
               <div className="bg-light-card dark:bg-dark-card rounded-lg border border-light-border dark:border-dark-border w-full">
                 <h3 className="text-xl font-bold p-4 pb-2">Diagrama de Gantt del Proyecto</h3>
                 <div className="overflow-x-auto p-4 gantt-scrollbar">
                    <GanttChart project={project} tasks={tasks} />
                 </div>
               </div>
             );
      case 'Ishikawa':
            return <IshikawaDiagram project={project} />;
      default:
        return null;
    }
  };

  return (
    <>
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div>
            <button onClick={onBackToList} className="flex items-center text-sm font-medium text-light-text-secondary dark:text-dark-text-secondary hover:text-brand-primary dark:hover:text-brand-accent mb-2 transition-colors">
                <ArrowLeftIcon className="h-4 w-4 mr-2" />
                Volver a Proyectos
            </button>
            <h1 className="text-3xl font-bold tracking-tight">{project.name}</h1>
            <p className="text-light-text-secondary dark:text-dark-text-secondary mt-1">{project.description}</p>
        </div>
        {canDeleteProject && (
            <button onClick={() => setDeleteModalOpen(true)} className="flex items-center px-4 py-2 text-sm font-medium rounded-md text-red-600 dark:text-red-400 bg-red-500/10 hover:bg-red-500/20 transition-colors">
                <TrashIcon className="h-5 w-5 mr-2" />
                Eliminar
            </button>
        )}
      </div>

      <div className="border-b border-light-border dark:border-dark-border mb-6">
        <nav className="-mb-px flex space-x-6">
          {tabs.map(tab => (
            <button 
              key={tab} 
              onClick={() => setActiveTab(tab)}
              className={`whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm transition-all duration-200 ${activeTab === tab ? 'border-brand-primary text-brand-primary' : 'border-transparent text-light-text-secondary dark:text-dark-text-secondary hover:text-light-text dark:hover:text-dark-text'}`}
            >
              {tab}
            </button>
          ))}
        </nav>
      </div>

      <div className="overflow-hidden">
        {renderActiveTabContent()}
      </div>

      {/* --- Report Preview Modal --- */}
      {previewPdfUrl && (
          <div className="fixed inset-0 bg-black/80 z-[60] flex items-center justify-center p-4 animate-fade-in" onClick={() => {setPreviewPdfUrl(null); setReportDoc(null);}}>
              <div className="bg-light-card dark:bg-dark-card w-full max-w-5xl h-[90vh] rounded-xl flex flex-col overflow-hidden shadow-2xl border border-light-border dark:border-dark-border" onClick={e => e.stopPropagation()}>
                  <header className="p-4 border-b border-light-border dark:border-dark-border flex justify-between items-center bg-light-bg dark:bg-dark-bg/50">
                      <div className="flex items-center gap-3">
                          <DocumentTextIcon className="h-6 w-6 text-brand-primary" />
                          <h2 className="text-lg font-bold">Previsualización de Reporte Corporativo</h2>
                      </div>
                      <div className="flex items-center gap-3">
                          <button 
                            onClick={handleDownloadReport}
                            className="flex items-center px-4 py-2 bg-brand-primary text-white text-sm font-bold rounded-lg hover:bg-brand-secondary transition-colors"
                          >
                              <DocumentDownloadIcon className="h-5 w-5 mr-2" />
                              Descargar Reporte
                          </button>
                          <button 
                            onClick={() => {setPreviewPdfUrl(null); setReportDoc(null);}}
                            className="p-2 hover:bg-red-100 dark:hover:bg-red-900/30 text-red-500 rounded-full transition-colors"
                          >
                              <XIcon className="h-6 w-6" />
                          </button>
                      </div>
                  </header>
                  <div className="flex-1 bg-gray-500 overflow-hidden">
                      <iframe 
                        src={previewPdfUrl} 
                        className="w-full h-full border-none"
                        title="Report Preview"
                      />
                  </div>
              </div>
          </div>
      )}

      <ConfirmationModal
        isOpen={isDeleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        onConfirm={handleDeleteConfirm}
        title="Eliminar Proyecto"
        message={`¿Estás seguro de que quieres eliminar el proyecto "${project.name}"? Esta acción no se puede deshacer y borrará toda la información relacionada.`}
      />

      <ConfirmationModal
        isOpen={isIshikawaConfirmOpen}
        onClose={() => setIsIshikawaConfirmOpen(false)}
        onConfirm={handleToggleIshikawa}
        title={project.ishikawaEnabled ? "Deshabilitar Ishikawa" : "Habilitar Ishikawa"}
        message={`¿Estás seguro de que quieres ${project.ishikawaEnabled ? 'deshabilitar' : 'habilitar'} la sección de Ishikawa para este proyecto?`}
      />
    </>
  );
};

export default ProjectDetailView;

import { Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle, VerticalAlign, ShadingType } from 'docx';
import { GoogleGenAI } from '@google/genai';
import { Project, ProjectTask, IshikawaDiagramData, Document as AppDocument } from '../types';

interface ReportData {
    project: Project;
    tasks: ProjectTask[];
    documents: AppDocument[];
    ishikawa?: IshikawaDiagramData | null;
}

export const generateCorporateReport = async (data: ReportData, apiKey: string): Promise<Blob> => {
    const { project, tasks, documents, ishikawa } = data;
    const ai = new GoogleGenAI({ apiKey });

    // 1. Preparar contexto para la IA
    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.status === 'completed');
    const failedTasks = tasks.filter(t => t.status === 'failed');
    const progress = totalTasks > 0 ? Math.round((completedTasks.length / totalTasks) * 100) : 0;

    const contextPrompt = `
        Genera el contenido textual para un REPORTE CORPORATIVO DE PROYECTO en formato profesional.
        PROYECTO: "${project.name}"
        OBJETIVO: "${project.objective}"
        ESTADÍSTICAS: Avance ${progress}%, ${failedTasks.length} incidencias registradas.
        NECESITO:
        1. RESUMEN EJECUTIVO (Síntesis estratégica).
        2. ANÁLISIS DE RIESGOS (Basado en las fallas: ${failedTasks.map(t => t.comments).join(', ')}).
        Devuelve JSON: {"executiveSummary": "...", "riskAnalysis": "..."}
    `;

    let aiContent = { 
        executiveSummary: project.executiveSummary || 'Sin resumen ejecutivo registrado.', 
        riskAnalysis: 'Control de riesgos operativo sin desviaciones críticas.' 
    };

    try {
        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: contextPrompt,
            config: { responseMimeType: "application/json" }
        });
        const parsed = JSON.parse(result.text);
        aiContent.executiveSummary = project.executiveSummary || parsed.executiveSummary;
        aiContent.riskAnalysis = parsed.riskAnalysis;
    } catch (e) {
        console.warn("AI Synthesis bypassed", e);
    }

    // 2. Construir Documento Word
    const doc = new Document({
        sections: [
            {
                properties: {},
                children: [
                    // Portada
                    new Paragraph({
                        text: "REPORTE CORPORATIVO DE PROYECTO",
                        heading: HeadingLevel.TITLE,
                        alignment: AlignmentType.CENTER,
                        spacing: { before: 2000, after: 400 },
                    }),
                    new Paragraph({
                        text: "UAD SYSTEM v2.5",
                        alignment: AlignmentType.CENTER,
                        spacing: { after: 2000 },
                    }),
                    new Paragraph({
                        text: project.name.toUpperCase(),
                        heading: HeadingLevel.HEADING_1,
                        alignment: AlignmentType.CENTER,
                        spacing: { after: 1200 },
                    }),
                    new Paragraph({
                        children: [
                            new TextRun({ text: "Responsable: ", bold: true }),
                            new TextRun(project.leader || 'No asignado'),
                        ],
                        spacing: { after: 200 },
                    }),
                    new Paragraph({
                        children: [
                            new TextRun({ text: "Periodo: ", bold: true }),
                            new TextRun(`${project.startDate} a ${project.endDate || 'Activo'}`),
                        ],
                        spacing: { after: 4000 },
                    }),
                    new Paragraph({
                        text: "Suave y Facil S.A. de C.V. - Documento Confidencial",
                        alignment: AlignmentType.CENTER,
                    }),

                    // 1. Resumen Ejecutivo
                    new Paragraph({ text: "1. RESUMEN EJECUTIVO", heading: HeadingLevel.HEADING_2, spacing: { before: 800, after: 400 }, pageBreakBefore: true }),
                    new Paragraph({ text: aiContent.executiveSummary, spacing: { after: 400 } }),

                    // 2. Información General
                    new Paragraph({ text: "2. INFORMACIÓN GENERAL", heading: HeadingLevel.HEADING_2, spacing: { before: 400, after: 400 } }),
                    new Table({
                        width: { size: 100, type: WidthType.PERCENTAGE },
                        rows: [
                            new TableRow({
                                children: [
                                    new TableCell({ children: [new Paragraph({ text: "Objetivo", bold: true })], width: { size: 30, type: WidthType.PERCENTAGE } }),
                                    new TableCell({ children: [new Paragraph(project.objective)], width: { size: 70, type: WidthType.PERCENTAGE } }),
                                ]
                            }),
                            new TableRow({
                                children: [
                                    new TableCell({ children: [new Paragraph({ text: "Avance Real", bold: true })] }),
                                    new TableCell({ children: [new Paragraph(`${progress}%`)] }),
                                ]
                            })
                        ]
                    }),

                    // 3. Ejecución de Tareas
                    new Paragraph({ text: "3. GESTIÓN DE TAREAS", heading: HeadingLevel.HEADING_2, spacing: { before: 800, after: 400 } }),
                    new Table({
                        width: { size: 100, type: WidthType.PERCENTAGE },
                        rows: [
                            new TableRow({
                                children: [
                                    new TableCell({ children: [new Paragraph({ text: "Tarea", bold: true })], shading: { fill: "f3f4f6", type: ShadingType.CLEAR } }),
                                    new TableCell({ children: [new Paragraph({ text: "Estado", bold: true })], shading: { fill: "f3f4f6", type: ShadingType.CLEAR } }),
                                    new TableCell({ children: [new Paragraph({ text: "Responsable", bold: true })], shading: { fill: "f3f4f6", type: ShadingType.CLEAR } }),
                                ]
                            }),
                            ...tasks.map(t => new TableRow({
                                children: [
                                    new TableCell({ children: [new Paragraph(t.title)] }),
                                    new TableCell({ children: [new Paragraph(t.status === 'completed' ? 'Éxito' : t.status === 'failed' ? 'Incidencia' : 'Pendiente')] }),
                                    new TableCell({ children: [new Paragraph(t.assignedTo || 'N/A')] }),
                                ]
                            }))
                        ]
                    }),

                    // 4. Análisis de Riesgos
                    new Paragraph({ text: "4. ANÁLISIS DE RIESGOS", heading: HeadingLevel.HEADING_2, spacing: { before: 800, after: 400 } }),
                    new Paragraph({ text: aiContent.riskAnalysis }),

                    // 5. Cierre y Resultados
                    new Paragraph({ text: "5. CONCLUSIONES", heading: HeadingLevel.HEADING_2, spacing: { before: 800, after: 400 } }),
                    new Paragraph({ text: project.finalConclusions || "El proyecto se encuentra en cumplimiento bajo los estándares de calidad establecidos.", spacing: { after: 1200 } }),

                    // Firmas
                    new Table({
                        width: { size: 100, type: WidthType.PERCENTAGE },
                        borders: {
                            top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE },
                            left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE },
                            insideHorizontal: { style: BorderStyle.NONE }, insideVertical: { style: BorderStyle.NONE },
                        },
                        rows: [
                            new TableRow({
                                children: [
                                    new TableCell({ 
                                        children: [
                                            new Paragraph({ text: "__________________________", alignment: AlignmentType.CENTER }),
                                            new Paragraph({ text: "Líder de Proyecto", alignment: AlignmentType.CENTER })
                                        ] 
                                    }),
                                    new TableCell({ 
                                        children: [
                                            new Paragraph({ text: "__________________________", alignment: AlignmentType.CENTER }),
                                            new Paragraph({ text: "Dirección de Calidad", alignment: AlignmentType.CENTER })
                                        ] 
                                    }),
                                ]
                            })
                        ]
                    })
                ],
            },
        ],
    });

    return await Packer.toBlob(doc);
};

import React, { useState, useEffect, useMemo } from 'react';
import { Project, ProjectTask, ProjectStatus, Document, Folder, UserPermissions, User } from '../../types';
import { ArrowLeftIcon, TrashIcon, PencilAltIcon, SparklesIcon, DocumentTextIcon, RefreshIcon, XIcon, DocumentDownloadIcon } from '../Icons';
import ConfirmationModal from './ConfirmationModal';
import ProjectTasksTab from './ProjectTasksTab';
import ProjectDocumentsTab from './ProjectDocumentsTab';
import GanttChart from './GanttChart';
import IshikawaDiagram from './IshikawaDiagram';
import { generateCorporateReport } from '../../services/reportService';
import { getIshikawaDiagram, getGeminiApiKey } from '../../services/supabaseService';
import Spinner from '../Spinner';
import FileViewerModal from '../FileViewerModal';

interface ProjectDetailViewProps {
  project: Project;
  tasks: ProjectTask[];
  documents: Document[];
  folders: Folder[];
  onBackToList: () => void;
  onDeleteProject: (id: string) => void;
  onSaveProject: (project: Project) => void;
  onAddTask: (projectId: string, details: { title: string; startDate: string; duration: number; assignedTo: string }, parentId?: string | null) => void;
  onToggleTask: (id: string) => void;
  onUpdateTask: (task: ProjectTask) => void;
  onDeleteTask: (id: string) => void;
  onAddDocument: (file: File, folderId: string, projectId: string | null) => Promise<void>;
  onDeleteDocument: (doc: Document) => Promise<void>;
  userPermissions: UserPermissions | null;
  user: User;
}

const ProjectDetailView: React.FC<ProjectDetailViewProps> = (props) => {
  const { 
      project, tasks, documents, folders, onBackToList, onDeleteProject, 
      onSaveProject, onAddTask, onToggleTask, onUpdateTask, onDeleteTask,
      onAddDocument, onDeleteDocument, userPermissions, user
  } = props;
  const [activeTab, setActiveTab] = useState('Resumen');
  const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);
  const [isIshikawaConfirmOpen, setIsIshikawaConfirmOpen] = useState(false);
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);

  // --- Report Preview State ---
  const [previewFile, setPreviewFile] = useState<{ id: string; url: string; name: string; mimeType: string; } | null>(null);

  const [isEditing, setIsEditing] = useState(false);
  const [editableProject, setEditableProject] = useState<Project>(project);

  useEffect(() => {
    setEditableProject(project);
    setIsEditing(false); 
  }, [project]);

  const tabs = useMemo(() => {
      const baseTabs = ['Resumen', 'Tareas', 'Documentos', 'Gantt'];
      if (project.ishikawaEnabled) {
          baseTabs.push('Ishikawa');
      }
      return baseTabs;
  }, [project.ishikawaEnabled]);

  const projectDocuments = useMemo(() => documents.filter(doc => doc.projectId === project.id), [documents, project.id]);

  const progress = useMemo(() => {
    const total = tasks.length;
    if (total === 0) return 0;
    return Math.round((tasks.filter(t => t.status === 'completed').length / total) * 100);
  }, [tasks]);

  const handleDeleteConfirm = () => {
    onDeleteProject(project.id);
    setDeleteModalOpen(false);
  };

  const handleToggleIshikawa = () => {
      const updatedProject = { ...project, ishikawaEnabled: !project.ishikawaEnabled };
      onSaveProject(updatedProject);
      setIsIshikawaConfirmOpen(false);
      if (!updatedProject.ishikawaEnabled && activeTab === 'Ishikawa') {
          setActiveTab('Resumen');
      }
  };

  const handleGenerateReport = async () => {
      setIsGeneratingReport(true);
      try {
          const apiKey = await getGeminiApiKey();
          const ishikawaData = project.ishikawaEnabled ? await getIshikawaDiagram(project.id) : null;

          const wordBlob = await generateCorporateReport({
              project,
              tasks,
              documents: projectDocuments,
              ishikawa: ishikawaData
          }, apiKey);

          const url = URL.createObjectURL(wordBlob);
          setPreviewFile({
              id: 'temp-report',
              url: url,
              name: `REPORTE_${project.name.replace(/\s+/g, '_')}.docx`,
              mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
          });

      } catch (error) {
          console.error("Report Generation Error:", error);
          alert("Error al generar el reporte corporativo.");
      } finally {
          setIsGeneratingReport(false);
      }
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setEditableProject(prev => ({ ...prev, [name]: value }));
  };

  const handleSave = () => {
    onSaveProject(editableProject);
    setIsEditing(false);
  };

  const handleCancel = () => {
    setEditableProject(project); 
    setIsEditing(false);
  };

  const canEditProject = userPermissions?.proyectos?.canEdit ?? false;
  const canDeleteProject = userPermissions?.proyectos?.canDelete ?? false;
  const canManageTasks = userPermissions?.proyectos?.canManageTasks ?? false;

  const renderActiveTabContent = () => {
    switch (activeTab) {
      case 'Tareas':
        return <ProjectTasksTab 
                  project={project}
                  tasks={tasks} 
                  onAddTask={(details, parentId) => onAddTask(project.id, details, parentId)}
                  onToggleTask={onToggleTask}
                  onUpdateTask={onUpdateTask}
                  onDeleteTask={onDeleteTask}
                  isEditor={canManageTasks}
                />;
      case 'Resumen':
        return (
          <div className="space-y-6">
            <div className="space-y-4 bg-light-card dark:bg-dark-card p-6 rounded-lg border border-light-border dark:border-dark-border">
              <div className="flex justify-between items-center mb-2">
                  <h3 className="text-lg font-bold">Información del Proyecto</h3>
                  <div className="flex items-center gap-3">
                      <button 
                        onClick={handleGenerateReport}
                        disabled={isGeneratingReport}
                        className={`flex items-center text-xs font-bold uppercase tracking-widest px-4 py-2 rounded bg-slate-900 dark:bg-slate-800 text-cyan-400 border border-cyan-500/30 hover:border-cyan-500 hover:shadow-[0_0_10px_rgba(6,182,212,0.3)] transition-all disabled:opacity-50`}
                      >
                        {isGeneratingReport ? <Spinner size="sm" /> : <DocumentTextIcon className="h-4 w-4 mr-2" />}
                        {isGeneratingReport ? 'Generando...' : 'VISTA PREVIA REPORTE (WORD)'}
                      </button>

                      {canEditProject && (
                        <button 
                            onClick={() => setIsIshikawaConfirmOpen(true)}
                            className={`flex items-center text-xs font-bold uppercase tracking-wider px-3 py-1.5 rounded-full border transition-all ${project.ishikawaEnabled ? 'bg-brand-primary/10 border-brand-primary text-brand-primary' : 'bg-gray-100 dark:bg-gray-800 border-gray-300 dark:border-gray-600 text-gray-500'}`}
                        >
                            <SparklesIcon className="h-3 w-3 mr-1.5" />
                            Ishikawa: {project.ishikawaEnabled ? 'ON' : 'OFF'}
                        </button>
                      )}
                      {canEditProject && !isEditing && (
                          <button 
                              onClick={() => setIsEditing(true)}
                              className="flex items-center text-sm font-medium text-brand-primary hover:text-brand-secondary"
                          >
                              <PencilAltIcon className="h-4 w-4 mr-1" />
                              Editar
                          </button>
