/**
 * Crea un párrafo para celdas con formato de etiqueta (fondo oscuro, texto blanco pequeño)
 */
const createLabelParagraph = (text: string) => new Paragraph({
    children: [new TextRun({ text, bold: true, size: 16, color: "FFFFFF", font: "Arial" })],
    alignment: AlignmentType.CENTER
});

/**
 * Crea un párrafo para celdas con formato de valor (texto blanco negrita)
 */
const createValueParagraph = (text: string) => new Paragraph({
    children: [new TextRun({ text, bold: true, size: 20, color: "FFFFFF", font: "Arial" })],
    alignment: AlignmentType.CENTER
});

/**
 * Función auxiliar para crear un párrafo robusto dentro de una celda del cuerpo.
 */
const createSafeCellParagraph = (text: string | undefined | null, isBold: boolean = false) => {
    const content = (text || '').trim() || '---';
    return new Paragraph({
        children: [new TextRun({ text: content, bold: isBold, font: "Arial", size: 22 })],
        alignment: AlignmentType.LEFT,
        spacing: { before: 80, after: 80 }
    });
};

export const generateCorporateReport = async (data: ReportData, apiKey: string): Promise<Blob> => {
    const { project, tasks, documents, ishikawa } = data;
    const ai = new GoogleGenAI({ apiKey });

    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.status === 'completed');
    const failedTasks = tasks.filter(t => t.status === 'failed');
    const progress = totalTasks > 0 ? Math.round((completedTasks.length / totalTasks) * 100) : 0;

    // Configuración de metadatos basada en la imagen
    const docCode = "CVD-PMC-PR-01";
    const docVersion = "02";
    const docDate = new Date().toISOString().split('T')[0];

    let aiContent = { 
        executiveSummary: project.executiveSummary || 'Sin resumen ejecutivo registrado.', 
        riskAnalysis: 'Control de riesgos operativo sin desviaciones críticas detectadas.' 
    };

    try {
        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Genera un breve resumen ejecutivo y análisis de riesgos para el proyecto "${project.name}" con ${failedTasks.length} incidencias. Devuelve JSON: {"executiveSummary": "...", "riskAnalysis": "..."}`,
            config: { responseMimeType: "application/json" }
        });
        const parsed = JSON.parse(result.text);
        aiContent.executiveSummary = project.executiveSummary || parsed.executiveSummary;
        aiContent.riskAnalysis = parsed.riskAnalysis;
    } catch (e) { console.warn("AI Synthesis bypassed", e); }

    const doc = new Document({
        sections: [{
            properties: {
                page: { margin: { top: 1200, bottom: 1200, left: 1200, right: 1200 } }
            },
            headers: {
                default: new Header({
                    children: [
                        new Table({
                            width: { size: 100, type: WidthType.PERCENTAGE },
                            rows: [
                                // Fila 1: Logo y Título Principal
                                new TableRow({
                                    children: [
                                        new TableCell({
                                            children: [new Paragraph({ children: [new TextRun({ text: "cvdirecto", bold: true, color: "FFFFFF", size: 36 })], alignment: AlignmentType.CENTER })],
                                            shading: { fill: "1F1F1F", type: ShadingType.CLEAR },
                                            width: { size: 25, type: WidthType.PERCENTAGE },
                                            verticalAlign: VerticalAlign.CENTER
                                        }),
                                        new TableCell({
                                            children: [
                                                new Paragraph({ 
                                                    children: [new TextRun({ text: "ELABORACIÓN DE PROCEDIMIENTOS", bold: true, color: "FFFFFF", size: 28 })],
                                                    alignment: AlignmentType.CENTER 
                                                }),
                                                new Paragraph({ 
                                                    children: [new TextRun({ text: "NORMALIZADOS DE OPERACIONES", bold: true, color: "FFFFFF", size: 28 })],
                                                    alignment: AlignmentType.CENTER 
                                                })
                                            ],
                                            shading: { fill: "1F1F1F", type: ShadingType.CLEAR },
                                            width: { size: 75, type: WidthType.PERCENTAGE },
                                            verticalAlign: VerticalAlign.CENTER
                                        })
                                    ]
                                }),
                                // Fila 2: Etiquetas de metadatos
                                new TableRow({
                                    children: [
                                        new TableCell({ children: [createLabelParagraph("Tipo de documento")], shading: { fill: "333333" } }),
                                        new TableCell({ children: [createLabelParagraph("Código")], shading: { fill: "333333" } }),
                                        new TableCell({ children: [createLabelParagraph("Fecha de emisión")], shading: { fill: "333333" } }),
                                        new TableCell({ children: [createLabelParagraph("Fecha de revisión")], shading: { fill: "333333" } }),
                                        new TableCell({ children: [createLabelParagraph("Versión")], shading: { fill: "333333" } }),
                                        new TableCell({ children: [createLabelParagraph("Sustituye a")], shading: { fill: "333333" } }),
                                    ]
                                }),
                                // Fila 3: Valores de metadatos
                                new TableRow({
                                    children: [
                                        new TableCell({ children: [createValueParagraph("PROCEDIMIENTO")], shading: { fill: "1F1F1F" } }),
                                        new TableCell({ children: [createValueParagraph(docCode)], shading: { fill: "1F1F1F" } }),
                                        new TableCell({ children: [createValueParagraph(project.startDate || docDate)], shading: { fill: "1F1F1F" } }),
                                        new TableCell({ children: [createValueParagraph(project.endDate || "2027-08-29")], shading: { fill: "1F1F1F" } }),
                                        new TableCell({ children: [createValueParagraph(docVersion)], shading: { fill: "1F1F1F" } }),
                                        new TableCell({ children: [createValueParagraph("01")], shading: { fill: "1F1F1F" } }),
                                    ]
                                })
                            ]
                        })
                    ]
                })
            },
            footers: {
                default: new Footer({
                    children: [
                        new Paragraph({
                            children: [
                                new TextRun({ 
                                    text: `${docCode}, V${docVersion}. Este documento es propiedad de Suave y Fácil S. A. de C.V. Queda prohibido su reproducción parcial o total sin previa autorización.`,
                                    italics: true,
                                    size: 18,
                                    color: "333333"
                                })
                            ],
                            alignment: AlignmentType.LEFT,
                            border: { top: { style: BorderStyle.SINGLE, size: 1, color: "999999" } },
                            spacing: { before: 200 }
                        })
                    ]
                })
            },
            children: [
                new Paragraph({ text: (project.name || 'PROYECTO').toUpperCase(), heading: HeadingLevel.HEADING_1, spacing: { before: 400, after: 400 } }),

                new Paragraph({ text: "1. RESUMEN EJECUTIVO", heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 200 } }),
                new Paragraph({ children: [new TextRun({ text: aiContent.executiveSummary })], spacing: { after: 300 } }),

                new Paragraph({ text: "2. INFORMACIÓN GENERAL", heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 200 } }),
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [
                        new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph("Objetivo Estratégico", true)], width: { size: 30, type: WidthType.PERCENTAGE }, shading: { fill: "F3F4F6" } }),
                                new TableCell({ children: [createSafeCellParagraph(project.objective || 'Sin objetivo')], width: { size: 70, type: WidthType.PERCENTAGE } }),
                            ]
                        }),
                        new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph("Líder de Proyecto", true)], shading: { fill: "F3F4F6" } }),
                                new TableCell({ children: [createSafeCellParagraph(project.leader || "No asignado")] }),
                            ]
                        }),
                        new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph("Avance de Obra", true)], shading: { fill: "F3F4F6" } }),
                                new TableCell({ children: [createSafeCellParagraph(`${progress}%`)] }),
                            ]
                        })
                    ]
                }),

                new Paragraph({ text: "3. GESTIÓN DE TAREAS", heading: HeadingLevel.HEADING_2, spacing: { before: 400, after: 200 } }),
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [
                        new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph("Tarea / Actividad", true)], shading: { fill: "D1D5DB" } }),
                                new TableCell({ children: [createSafeCellParagraph("Estado", true)], shading: { fill: "D1D5DB" } }),
                                new TableCell({ children: [createSafeCellParagraph("Responsable", true)], shading: { fill: "D1D5DB" } }),
                            ]
                        }),
                        ...(tasks.length > 0 ? tasks.map(t => new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph(t.title)] }),
                                new TableCell({ children: [createSafeCellParagraph(t.status === 'completed' ? 'ÉXITO' : t.status === 'failed' ? 'INCIDENCIA' : 'PENDIENTE')] }),
                                new TableCell({ children: [createSafeCellParagraph(t.assignedTo || project.leader)] }),
                            ]
                        })) : [new TableRow({ children: [new TableCell({ columnSpan: 3, children: [createSafeCellParagraph("Sin tareas registradas.", false)] })] })])
                    ]
                }),

                new Paragraph({ text: "4. ANÁLISIS DE RIESGOS", heading: HeadingLevel.HEADING_2, spacing: { before: 400, after: 200 } }),
                new Paragraph({ children: [new TextRun({ text: aiContent.riskAnalysis })] }),

                new Paragraph({ text: "5. CONCLUSIONES", heading: HeadingLevel.HEADING_2, spacing: { before: 400, after: 200 } }),
                new Paragraph({ text: project.finalConclusions || "El proyecto se ha ejecutado conforme a los lineamientos de calidad establecidos." }),
            ]
        }]
    });

    return await Packer.toBlob(doc);
};

