                   <div className="flex items-center gap-1 bg-red-500/10 text-red-600 px-2 py-1 rounded"><span className="w-2 h-2 rounded-full bg-red-500"></span>{tasks.filter(t => t.status === 'failed').length} Incidencias</div>
