export default ProjectDetailView;

import { Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle, VerticalAlign, ShadingType, Header, Footer } from 'docx';
import { GoogleGenAI } from '@google/genai';
import { Project, ProjectTask, IshikawaDiagramData, Document as AppDocument } from '../types';
import { downloadTemplateAsBytes } from './supabaseService';
// Importamos librerías para templating (via CDN / ESM)
import PizZip from 'pizzip';
import Docxtemplater from 'docxtemplater';

interface ReportData {
    project: Project;
    tasks: ProjectTask[];
    documents: AppDocument[];
    ishikawa?: IshikawaDiagramData | null;
}

/**
 * Función auxiliar para crear un párrafo robusto dentro de una celda del cuerpo (diseño manual).
 */
const createSafeCellParagraph = (text: string | undefined | null, isBold: boolean = false) => {
    const content = (text || '').trim() || '---';
    return new Paragraph({
        children: [new TextRun({ text: content, bold: isBold, font: "Arial", size: 22 })],
        alignment: AlignmentType.LEFT,
        spacing: { before: 80, after: 80 }
    });
};

/**
 * Genera el reporte corporativo. 
 * Si el proyecto tiene una ruta de plantilla, la usa para inyectar datos.
 * Si no, genera el reporte con el diseño estándar.
 */
export const generateCorporateReport = async (data: ReportData, apiKey: string): Promise<Blob> => {
    const { project, tasks, documents, ishikawa } = data;
    const ai = new GoogleGenAI({ apiKey });

    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.status === 'completed');
    const failedTasks = tasks.filter(t => t.status === 'failed');
    const progress = totalTasks > 0 ? Math.round((completedTasks.length / totalTasks) * 100) : 0;

    let aiContent = { 
        executiveSummary: project.executiveSummary || 'Sin resumen ejecutivo registrado.', 
        riskAnalysis: 'Control de riesgos operativo sin desviaciones críticas detectadas.' 
    };

    try {
        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Genera un breve resumen ejecutivo y análisis de riesgos para el proyecto "${project.name}" con ${failedTasks.length} incidencias. Devuelve JSON: {"executiveSummary": "...", "riskAnalysis": "..."}`,
            config: { responseMimeType: "application/json" }
        });
        const parsed = JSON.parse(result.text);
        aiContent.executiveSummary = project.executiveSummary || parsed.executiveSummary;
        aiContent.riskAnalysis = parsed.riskAnalysis;
    } catch (e) { 
        console.warn("AI Synthesis bypassed", e); 
    }

    // --- OPCIÓN A: USAR PLANTILLA PERSONALIZADA SI EXISTE ---
    if (project.reportTemplatePath) {
        try {
            const templateBytes = await downloadTemplateAsBytes(project.reportTemplatePath);
            const zip = new PizZip(templateBytes);
            const doc = new Docxtemplater(zip, {
                paragraphLoop: true,
                linebreaks: true,
            });

            // Preparar datos para inyectar en las etiquetas del Word
            const reportData = {
                NOMBRE_PROYECTO: project.name.toUpperCase(),
                OBJETIVO: project.objective,
                AVANCE: `${progress}%`,
                LIDER: project.leader || "No asignado",
                RESUMEN_EJECUTIVO: aiContent.executiveSummary,
                ANALISIS_RIESGOS: aiContent.riskAnalysis,
                CONCLUSIONES: project.finalConclusions || "Pendiente de cierre formal.",
                TAREAS: tasks.map(t => ({
                    titulo: t.title,
                    estado: t.status === 'completed' ? 'ÉXITO' : t.status === 'failed' ? 'INCIDENCIA' : 'PENDIENTE',
                    responsable: t.assignedTo || project.leader || '---'
                }))
            };

            doc.render(reportData);
            const out = doc.getZip().generate({
                type: "blob",
                mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            });
            return out;

        } catch (error) {
            console.error("Error al procesar la plantilla Word:", error);
            // Si falla la plantilla, el código sigue y genera el reporte manual por defecto
        }
    }

    // --- OPCIÓN B: DISEÑO MANUAL POR DEFECTO (Header/Footer Hardcoded) ---
    const docCode = "CVD-PMC-PR-01";
    const docVersion = "02";
    const docDate = new Date().toISOString().split('T')[0];

    const manualDoc = new Document({
        sections: [{
            properties: {
                page: { margin: { top: 1200, bottom: 1200, left: 1200, right: 1200 } }
            },
            headers: {
                default: new Header({
                    children: [
                        new Table({
                            width: { size: 100, type: WidthType.PERCENTAGE },
                            rows: [
                                new TableRow({
                                    children: [
                                        new TableCell({
                                            children: [new Paragraph({ children: [new TextRun({ text: "cvdirecto", bold: true, color: "FFFFFF", size: 36 })], alignment: AlignmentType.CENTER })],
                                            shading: { fill: "1F1F1F", type: ShadingType.CLEAR },
                                            width: { size: 25, type: WidthType.PERCENTAGE },
                                            verticalAlign: VerticalAlign.CENTER
                                        }),
                                        new TableCell({
                                            children: [
                                                new Paragraph({ children: [new TextRun({ text: "ELABORACIÓN DE PROCEDIMIENTOS", bold: true, color: "FFFFFF", size: 28 })], alignment: AlignmentType.CENTER }),
                                                new Paragraph({ children: [new TextRun({ text: "NORMALIZADOS DE OPERACIONES", bold: true, color: "FFFFFF", size: 28 })], alignment: AlignmentType.CENTER })
                                            ],
                                            shading: { fill: "1F1F1F", type: ShadingType.CLEAR },
                                            width: { size: 75, type: WidthType.PERCENTAGE },
                                            verticalAlign: VerticalAlign.CENTER
                                        })
                                    ]
                                })
                            ]
                        })
                    ]
                })
            },
            footers: {
                default: new Footer({
                    children: [
                        new Paragraph({
                            children: [new TextRun({ text: `${docCode}, V${docVersion}. Este documento es propiedad de Suave y Fácil S. A. de C.V. Queda prohibido su reproducción parcial o total sin previa autorización.`, italics: true, size: 18, color: "333333" })],
                            alignment: AlignmentType.LEFT,
                            border: { top: { style: BorderStyle.SINGLE, size: 1, color: "999999" } },
                            spacing: { before: 200 }
                        })
                    ]
                })
            },
            children: [
                new Paragraph({ text: (project.name || 'PROYECTO').toUpperCase(), heading: HeadingLevel.HEADING_1, spacing: { before: 400, after: 400 } }),
                new Paragraph({ text: "1. RESUMEN EJECUTIVO", heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 200 } }),
                new Paragraph({ children: [new TextRun({ text: aiContent.executiveSummary })], spacing: { after: 300 } }),
                new Paragraph({ text: "2. INFORMACIÓN GENERAL", heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 200 } }),
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [
                        new TableRow({ children: [new TableCell({ children: [createSafeCellParagraph("Objetivo Estratégico", true)], width: { size: 30, type: WidthType.PERCENTAGE }, shading: { fill: "F3F4F6" } }), new TableCell({ children: [createSafeCellParagraph(project.objective || 'Sin objetivo')], width: { size: 70, type: WidthType.PERCENTAGE } })] }),
                        new TableRow({ children: [new TableCell({ children: [createSafeCellParagraph("Líder de Proyecto", true)], shading: { fill: "F3F4F6" } }), new TableCell({ children: [createSafeCellParagraph(project.leader || "No asignado")] })] }),
                        new TableRow({ children: [new TableCell({ children: [createSafeCellParagraph("Avance de Obra", true)], shading: { fill: "F3F4F6" } }), new TableCell({ children: [createSafeCellParagraph(`${progress}%`)] })] })
                    ]
                }),
                new Paragraph({ text: "3. GESTIÓN DE TAREAS", heading: HeadingLevel.HEADING_2, spacing: { before: 400, after: 200 } }),
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [
                        new TableRow({ children: [new TableCell({ children: [createSafeCellParagraph("Tarea / Actividad", true)], shading: { fill: "D1D5DB" } }), new TableCell({ children: [createSafeCellParagraph("Estado", true)], shading: { fill: "D1D5DB" } }), new TableCell({ children: [createSafeCellParagraph("Responsable", true)], shading: { fill: "D1D5DB" } })] }),
                        ...(tasks.length > 0 ? tasks.map(t => new TableRow({ children: [new TableCell({ children: [createSafeCellParagraph(t.title)] }), new TableCell({ children: [createSafeCellParagraph(t.status === 'completed' ? 'ÉXITO' : t.status === 'failed' ? 'INCIDENCIA' : 'PENDIENTE')] }), new TableCell({ children: [createSafeCellParagraph(t.assignedTo || project.leader)] })] })) : [new TableRow({ children: [new TableCell({ columnSpan: 3, children: [createSafeCellParagraph("Sin tareas registradas.", false)] })] })])
                    ]
                }),
                new Paragraph({ text: "4. ANÁLISIS DE RIESGOS", heading: HeadingLevel.HEADING_2, spacing: { before: 400, after: 200 } }),
                new Paragraph({ children: [new TextRun({ text: aiContent.riskAnalysis })] }),
                new Paragraph({ text: "5. CONCLUSIONES", heading: HeadingLevel.HEADING_2, spacing: { before: 400, after: 200 } }),
                new Paragraph({ text: project.finalConclusions || "El proyecto se ha ejecutado conforme a los lineamientos de calidad establecidos." }),
            ]
        }]
    });

    return await Packer.toBlob(manualDoc);
};

