export const uploadReportTemplate = async (projectId: string, file: File): Promise<string> => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error('No autenticado');

    const filePath = `${user.id}/TEMPLATES/${projectId}-template.docx`;
    const { error: uploadError } = await supabase.storage.from('user_files').upload(filePath, file, { upsert: true });
    if (uploadError) throw uploadError;

    // Actualizar el proyecto con la ruta de la plantilla
    const { error: updateError } = await supabase.from('projects').update({ report_template_path: filePath }).eq('id', projectId);
    if (updateError) throw updateError;

    return filePath;
};

