    if (!user) throw new Error('User not authenticated');
    const filePath = `${user.id}/UPLOADS/${uuidv4()}-${sanitizeFileName(file.name)}`;
    const { error: uploadError } = await supabase.storage.from('user_files').upload(filePath, file);
    if (uploadError) throw uploadError;
};

import { Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle, VerticalAlign, ShadingType, ImageRun } from 'docx';
import { GoogleGenAI } from '@google/genai';
import { Project, ProjectTask, IshikawaDiagramData, Document as AppDocument } from '../types';
import { downloadTemplateAsBytes } from './supabaseService';
// Importamos librerías para templating (via CDN / ESM)
import PizZip from 'pizzip';
import Docxtemplater from 'docxtemplater';

interface ReportData {
    project: Project;
    tasks: ProjectTask[];
    documents: AppDocument[];
    ishikawa?: IshikawaDiagramData | null;
    ganttImage?: string; // Imagen base64 del diagrama de Gantt
}

/**
 * Función auxiliar para crear un párrafo robusto dentro de una celda del cuerpo (diseño manual).
 */
const createSafeCellParagraph = (text: string | undefined | null, isBold: boolean = false) => {
    const content = (text || '').trim() || '---';
    return new Paragraph({
        children: [new TextRun({ text: content, bold: isBold, font: "Arial", size: 22 })],
        alignment: AlignmentType.LEFT,
        spacing: { before: 80, after: 80 }
    });
};

/**
 * Genera el reporte corporativo. 
 * Si el proyecto tiene una ruta de plantilla, la usa para inyectar datos.
 * Si no, genera el reporte con el diseño estándar.
 */
export const generateCorporateReport = async (data: ReportData, apiKey: string): Promise<Blob> => {
    const { project, tasks, documents, ishikawa, ganttImage } = data;
    const ai = new GoogleGenAI({ apiKey });

    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.status === 'completed');
    const failedTasks = tasks.filter(t => t.status === 'failed');
    const progress = totalTasks > 0 ? Math.round((completedTasks.length / totalTasks) * 100) : 0;

    let aiContent = { 
        executiveSummary: project.executiveSummary || 'Sin resumen ejecutivo registrado.', 
        riskAnalysis: 'Control de riesgos operativo sin desviaciones críticas detectadas en el periodo actual.' 
    };

    try {
        const result = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Genera un breve resumen ejecutivo y análisis de riesgos para el proyecto "${project.name}" con ${failedTasks.length} incidencias. Devuelve JSON: {"executiveSummary": "...", "riskAnalysis": "..."}`,
            config: { responseMimeType: "application/json" }
        });
        const parsed = JSON.parse(result.text);
        aiContent.executiveSummary = project.executiveSummary || parsed.executiveSummary;
        aiContent.riskAnalysis = parsed.riskAnalysis;
    } catch (e) { 
        console.warn("AI Synthesis bypassed", e); 
    }

    // --- OPCIÓN A: USAR PLANTILLA PERSONALIZADA SI EXISTE ---
    if (project.reportTemplatePath) {
        try {
            const templateBytes = await downloadTemplateAsBytes(project.reportTemplatePath);
            const zip = new PizZip(templateBytes);
            const doc = new Docxtemplater(zip, {
                paragraphLoop: true,
                linebreaks: true,
            });

            // Preparar datos para inyectar en las etiquetas del Word
            const reportData = {
                NOMBRE_PROYECTO: project.name.toUpperCase(),
                OBJETIVO: project.objective,
                AVANCE: `${progress}%`,
                LIDER: project.leader || "No asignado",
                RESUMEN_EJECUTIVO: aiContent.executiveSummary,
                ANALISIS_RIESGOS: aiContent.riskAnalysis,
                CONCLUSIONES: project.finalConclusions || "Se concluye que el proyecto se encuentra bajo los parámetros de ejecución establecidos.",
                TAREAS: tasks.map(t => ({
                    titulo: t.title,
                    estado: t.status === 'completed' ? 'ÉXITO' : t.status === 'failed' ? 'INCIDENCIA' : 'PENDIENTE',
                    responsable: t.assignedTo || 'Responsable no Asignado'
                }))
            };

            doc.render(reportData);
            const out = doc.getZip().generate({
                type: "blob",
                mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            });
            return out;

        } catch (error) {
            console.error("Error al procesar la plantilla Word:", error);
            // Si falla la plantilla, el código sigue y genera el reporte manual por defecto
        }
    }

    // --- OPCIÓN B: DISEÑO MANUAL POR DEFECTO (Fallback) ---
    const manualDoc = new Document({
        sections: [{
            properties: {
                page: { margin: { top: 1200, bottom: 1200, left: 1200, right: 1200 } }
            },
            children: [
                new Paragraph({ text: "REPORTE CORPORATIVO DE PROYECTO", heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER, spacing: { before: 2000, after: 400 } }),
                new Paragraph({ text: (project.name || 'PROYECTO').toUpperCase(), heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, spacing: { after: 1200 } }),

                new Paragraph({ text: "1. RESUMEN EJECUTIVO", heading: HeadingLevel.HEADING_2, spacing: { before: 800, after: 400 }, pageBreakBefore: true }),
                new Paragraph({ children: [new TextRun({ text: aiContent.executiveSummary, font: "Arial", size: 24 })], spacing: { after: 400 } }),

                new Paragraph({ text: "2. INFORMACIÓN GENERAL", heading: HeadingLevel.HEADING_2, spacing: { before: 400, after: 400 } }),
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [
                        new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph("Objetivo Estratégico", true)], width: { size: 30, type: WidthType.PERCENTAGE }, shading: { fill: "F3F4F6" } }),
                                new TableCell({ children: [createSafeCellParagraph(project.objective || 'Sin objetivo')] }),
                            ]
                        }),
                        new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph("Líder de Proyecto", true)], shading: { fill: "F3F4F6" } }),
                                new TableCell({ children: [createSafeCellParagraph(project.leader || "No asignado")] }),
                            ]
                        }),
                        new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph("Avance de Obra", true)], shading: { fill: "F3F4F6" } }),
                                new TableCell({ children: [createSafeCellParagraph(`${progress}%`)] }),
                            ]
                        })
                    ]
                }),

                new Paragraph({ text: "3. GESTIÓN DE TAREAS", heading: HeadingLevel.HEADING_2, spacing: { before: 800, after: 400 } }),
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [
                        new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph("Tarea / Actividad", true)], shading: { fill: "D1D5DB" } }),
                                new TableCell({ children: [createSafeCellParagraph("Estado", true)], shading: { fill: "D1D5DB" } }),
                                new TableCell({ children: [createSafeCellParagraph("Responsable", true)], shading: { fill: "D1D5DB" } }),
                            ]
                        }),
                        ...(tasks.length > 0 ? tasks.map(t => new TableRow({
                            children: [
                                new TableCell({ children: [createSafeCellParagraph(t.title)] }),
                                new TableCell({ children: [createSafeCellParagraph(t.status === 'completed' ? 'ÉXITO' : t.status === 'failed' ? 'INCIDENCIA' : 'PENDIENTE')] }),
                                new TableCell({ children: [createSafeCellParagraph(t.assignedTo || 'Responsable no Asignado')] }),
                            ]
                        })) : [new TableRow({ children: [new TableCell({ columnSpan: 3, children: [createSafeCellParagraph("Sin tareas registradas.", false)] })] })]
                    ]
                }),

                new Paragraph({ text: "4. DIAGRAMA DE GANTT", heading: HeadingLevel.HEADING_2, spacing: { before: 800, after: 400 } }),
                ...(ganttImage ? [
                    new Paragraph({
                        children: [
                            new ImageRun({
                                data: ganttImage,
                                transformation: { width: 600, height: 320 }
                            })
                        ],
                        alignment: AlignmentType.CENTER
                    })
                ] : [
                    new Paragraph({ text: "Vista gráfica no disponible.", italics: true })
                ]),

                new Paragraph({ text: "5. ANÁLISIS DE RIESGOS", heading: HeadingLevel.HEADING_2, spacing: { before: 800, after: 400 } }),
                new Paragraph({ children: [new TextRun({ text: aiContent.riskAnalysis, font: "Arial", size: 24 })] }),

                new Paragraph({ text: "6. CONCLUSIONES", heading: HeadingLevel.HEADING_2, spacing: { before: 800, after: 400 } }),
                new Paragraph({ text: project.finalConclusions || "El proyecto se ha ejecutado conforme a los lineamientos de calidad establecidos." }),
            ]
        }]
    });

    return await Packer.toBlob(manualDoc);
};

import React, { useState, useEffect, useMemo } from 'react';
import html2canvas from 'html2canvas';
import { Project, ProjectTask, ProjectStatus, Document, Folder, UserPermissions, User } from '../../types';
import { ArrowLeftIcon, TrashIcon, PencilAltIcon, SparklesIcon, DocumentTextIcon, RefreshIcon, XIcon, DocumentDownloadIcon, UploadIcon } from '../Icons';
import ConfirmationModal from './ConfirmationModal';
import ProjectTasksTab from './ProjectTasksTab';
import ProjectDocumentsTab from './ProjectDocumentsTab';
import GanttChart from './GanttChart';
import IshikawaDiagram from './IshikawaDiagram';
import { generateCorporateReport } from '../../services/reportService';
import { getIshikawaDiagram, getGeminiApiKey, uploadReportTemplate } from '../../services/supabaseService';
import Spinner from '../Spinner';
import FileViewerModal from '../FileViewerModal';

interface ProjectDetailViewProps {
  project: Project;
  tasks: ProjectTask[];
  documents: Document[];
  folders: Folder[];
  onBackToList: () => void;
  onDeleteProject: (id: string) => void;
  onSaveProject: (project: Project) => void;
  onAddTask: (projectId: string, details: { title: string; startDate: string; duration: number; assignedTo: string }, parentId?: string | null) => void;
  onToggleTask: (id: string) => void;
  onUpdateTask: (task: ProjectTask) => void;
  onDeleteTask: (id: string) => void;
  onAddDocument: (file: File, folderId: string, projectId: string | null) => Promise<void>;
  onDeleteDocument: (doc: Document) => Promise<void>;
  userPermissions: UserPermissions | null;
  user: User;
}

const ProjectDetailView: React.FC<ProjectDetailViewProps> = (props) => {
  const { 
      project, tasks, documents, folders, onBackToList, onDeleteProject, 
      onSaveProject, onAddTask, onToggleTask, onUpdateTask, onDeleteTask,
      onAddDocument, onDeleteDocument, userPermissions, user
  } = props;
  const [activeTab, setActiveTab] = useState('Resumen');
  const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);
  const [isIshikawaConfirmOpen, setIsIshikawaConfirmOpen] = useState(false);
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);
  const [isDownloadingReport, setIsDownloadingReport] = useState(false);
  const [isUploadingTemplate, setIsUploadingTemplate] = useState(false);

  const [previewFile, setPreviewFile] = useState<{ id: string; url: string; name: string; mimeType: string; } | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editableProject, setEditableProject] = useState<Project>(project);

  useEffect(() => {
    setEditableProject(project);
    setIsEditing(false); 
  }, [project]);

  const tabs = useMemo(() => {
      const baseTabs = ['Resumen', 'Tareas', 'Documentos', 'Gantt'];
      if (project.ishikawaEnabled) baseTabs.push('Ishikawa');
      return baseTabs;
  }, [project.ishikawaEnabled]);

  const projectDocuments = useMemo(() => documents.filter(doc => doc.projectId === project.id), [documents, project.id]);

  const progress = useMemo(() => {
    const total = tasks.length;
    if (total === 0) return 0;
    return Math.round((tasks.filter(t => t.status === 'completed').length / total) * 100);
  }, [tasks]);

  const handleUploadTemplate = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      if (!file.name.endsWith('.docx')) {
          alert('Solo se admiten archivos .docx de Word.');
          return;
      }
      setIsUploadingTemplate(true);
      try {
          const path = await uploadReportTemplate(project.id, file);
          alert('Plantilla vinculada correctamente.');
          onSaveProject({ ...project, reportTemplatePath: path });
      } catch (error) {
          console.error(error);
          alert('Error al subir la plantilla.');
      } finally {
          setIsUploadingTemplate(false);
      }
  };

  const createReportBlob = async () => {
      const apiKey = await getGeminiApiKey();
      const ishikawaData = project.ishikawaEnabled ? await getIshikawaDiagram(project.id) : null;

      let ganttImageBase64 = undefined;
      try {
          const ganttElement = document.getElementById('gantt-capture-area');
          if (ganttElement) {
              const canvas = await html2canvas(ganttElement, {
                  useCORS: true,
                  scale: 1.5,
                  backgroundColor: '#ffffff',
                  logging: false
              });
              ganttImageBase64 = canvas.toDataURL('image/png');
          }
      } catch (err) { console.error("Error capturing Gantt:", err); }

      return await generateCorporateReport({
          project,
          tasks,
          documents: projectDocuments,
          ishikawa: ishikawaData,
          ganttImage: ganttImageBase64
      }, apiKey);
  };

  const handleGenerateReport = async () => {
      setIsGeneratingReport(true);
      try {
          const wordBlob = await createReportBlob();
          const url = URL.createObjectURL(wordBlob);
          setPreviewFile({
              id: 'temp-report',
              url: url,
              name: `REPORTE_${project.name.replace(/\s+/g, '_')}.docx`,
              mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
          });
      } catch (error) {
          alert("Error al generar la vista previa del reporte.");
      } finally {
          setIsGeneratingReport(false);
      }
  };

  const handleDownloadReport = async () => {
      setIsDownloadingReport(true);
      try {
          const wordBlob = await createReportBlob();
          const url = URL.createObjectURL(wordBlob);
          const link = document.createElement('a');
          link.href = url;
          link.download = `REPORTE_${project.name.replace(/\s+/g, '_')}.docx`;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          URL.revokeObjectURL(url);
      } catch (error) {
          alert("Error al descargar el reporte.");
      } finally {
          setIsDownloadingReport(false);
      }
  };

  const renderActiveTabContent = () => {
    switch (activeTab) {
      case 'Tareas':
        return <ProjectTasksTab project={project} tasks={tasks} onAddTask={(details, parentId) => onAddTask(project.id, details, parentId)} onToggleTask={onToggleTask} onUpdateTask={onUpdateTask} onDeleteTask={onDeleteTask} isEditor={userPermissions?.proyectos?.canManageTasks ?? false} />;
      case 'Resumen':
        return (
          <div className="space-y-6">
            <div className="space-y-4 bg-light-card dark:bg-dark-card p-6 rounded-lg border border-light-border dark:border-dark-border">
              <div className="flex justify-between items-center mb-2">
                  <h3 className="text-lg font-bold">Información del Proyecto</h3>
                  <div className="flex items-center gap-2">
                      <label className={`flex items-center text-[10px] font-black uppercase tracking-widest px-3 py-2 rounded border cursor-pointer transition-all ${project.reportTemplatePath ? 'bg-amber-500/10 border-amber-500 text-amber-500' : 'bg-slate-700/50 border-slate-600 text-slate-400 hover:border-brand-primary hover:text-brand-primary'}`}>
                          {isUploadingTemplate ? <Spinner size="sm" /> : <UploadIcon className="h-4 w-4 mr-2" />}
                          {project.reportTemplatePath ? 'PLANTILLA VINCULADA' : 'SUBIR PLANTILLA'}
                          <input type="file" accept=".docx" className="hidden" onChange={handleUploadTemplate} disabled={isUploadingTemplate} />
                      </label>

                      <button onClick={handleGenerateReport} disabled={isGeneratingReport} className="flex items-center text-[10px] font-black uppercase tracking-widest px-3 py-2 rounded bg-slate-900 text-cyan-400 border border-cyan-500/30 hover:border-cyan-500 transition-all disabled:opacity-50">
                        {isGeneratingReport ? <Spinner size="sm" /> : <DocumentTextIcon className="h-4 w-4 mr-2" />} VISTA PREVIA
                      </button>

                      <button onClick={handleDownloadReport} disabled={isDownloadingReport} className="flex items-center text-[10px] font-black uppercase tracking-widest px-3 py-2 rounded bg-green-950 text-green-400 border border-green-500/30 hover:border-green-400 transition-all disabled:opacity-50">
                        {isDownloadingReport ? <Spinner size="sm" /> : <DocumentDownloadIcon className="h-4 w-4 mr-2" />} DESCARGAR WORD
                      </button>

                      {isEditing ? (
                          <div className="flex gap-2">
                              <button onClick={() => setIsEditing(false)} className="text-xs font-bold uppercase text-gray-500 hover:text-gray-700">Cancelar</button>
                              <button onClick={() => { onSaveProject(editableProject); setIsEditing(false); }} className="text-xs font-bold uppercase text-brand-primary hover:text-brand-secondary">Guardar</button>
                          </div>
                      ) : (
                          <button onClick={() => setIsEditing(true)} className="flex items-center text-sm font-medium text-brand-primary hover:text-brand-secondary ml-2"><PencilAltIcon className="h-4 w-4 mr-1" /> Editar</button>
                      )}
                  </div>
              </div>

              {isEditing ? (
                  <div className="space-y-4">
                      <textarea name="objective" rows={2} value={editableProject.objective} onChange={e => setEditableProject({...editableProject, objective: e.target.value})} className="w-full p-2 border border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md text-sm"/>
                      <div className="grid grid-cols-2 gap-4">
                          <textarea placeholder="Resumen ejecutivo..." name="executiveSummary" rows={4} value={editableProject.executiveSummary} onChange={e => setEditableProject({...editableProject, executiveSummary: e.target.value})} className="w-full p-2 border border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md text-sm"/>
                          <textarea placeholder="Conclusiones..." name="finalConclusions" rows={4} value={editableProject.finalConclusions} onChange={e => setEditableProject({...editableProject, finalConclusions: e.target.value})} className="w-full p-2 border border-light-border dark:border-dark-border bg-light-bg dark:bg-dark-bg rounded-md text-sm"/>
                      </div>
                  </div>
              ) : (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  <div className="lg:col-span-2 space-y-4">
                      <h4 className="text-xs font-black text-brand-primary uppercase tracking-widest">Objetivo</h4>
                      <p className="text-sm text-light-text-secondary dark:text-dark-text-secondary whitespace-pre-wrap">{project.objective}</p>
                      {project.executiveSummary && (
                          <div className="mt-4">
                              <h4 className="text-xs font-black text-brand-primary uppercase tracking-widest">Resumen Ejecutivo</h4>
                              <p className="text-sm italic text-light-text-secondary dark:text-dark-text-secondary">"{project.executiveSummary}"</p>
                          </div>
                      )}
                  </div>
                  <div className="space-y-4 lg:border-l lg:pl-6 border-light-border dark:border-dark-border">
                      <h4 className="text-base font-bold">Detalles</h4>
                      <div className="text-xs font-semibold uppercase tracking-wider text-light-text-secondary dark:text-dark-text-secondary">Estado: {project.status}</div>
                      <div className="text-xs font-semibold uppercase tracking-wider text-light-text-secondary dark:text-dark-text-secondary">Líder: {project.leader || 'No asignado'}</div>
                  </div>
                </div>
              )}
            </div>
            <div className="bg-light-card dark:bg-dark-card p-6 rounded-lg border border-light-border dark:border-dark-border relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10"><RefreshIcon className="h-24 w-24 animate-spin-slow" /></div>
                <h3 className="text-lg font-bold mb-2">Avance Real ({progress}%)</h3>
                <div className="w-full bg-light-bg dark:bg-dark-bg rounded-full h-4">
                  <div className="bg-brand-primary h-full rounded-full transition-all duration-1000" style={{ width: `${progress}%` }}></div>
                </div>
            </div>
          </div>
        );
      case 'Documentos': return <ProjectDocumentsTab project={project} documents={projectDocuments} folders={folders} onAddDocument={onAddDocument} onDeleteDocument={onDeleteDocument} userPermissions={userPermissions} user={user} />;
      case 'Gantt': return (
        <div className="bg-light-card dark:bg-dark-card rounded-lg border border-light-border dark:border-dark-border w-full">
            <h3 className="text-xl font-bold p-4 pb-2">Diagrama de Gantt</h3>
            <div className="overflow-x-auto p-4 gantt-scrollbar"><GanttChart project={project} tasks={tasks} /></div>
        </div>
      );
      case 'Ishikawa': return <IshikawaDiagram project={project} />;
      default: return null;
    }
  };

  return (
    <>
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div>
            <button onClick={onBackToList} className="flex items-center text-sm font-medium text-light-text-secondary dark:text-dark-text-secondary hover:text-brand-primary mb-2 transition-colors">
                <ArrowLeftIcon className="h-4 w-4 mr-2" /> Volver a Proyectos
            </button>
            <h1 className="text-3xl font-bold tracking-tight">{project.name}</h1>
        </div>
        {userPermissions?.proyectos?.canDelete && (
            <button onClick={() => setDeleteModalOpen(true)} className="flex items-center px-4 py-2 text-sm font-medium rounded-md text-red-600 bg-red-500/10 hover:bg-red-500/20 transition-colors">
                <TrashIcon className="h-5 w-5 mr-2" /> Eliminar
            </button>
        )}
      </div>

      <div className="border-b border-light-border dark:border-dark-border mb-6">
        <nav className="-mb-px flex space-x-6">
          {tabs.map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm transition-all duration-200 ${activeTab === tab ? 'border-brand-primary text-brand-primary' : 'border-transparent text-light-text-secondary hover:text-light-text'}`}>{tab}</button>
          ))}
        </nav>
      </div>

      <div className="overflow-hidden">{renderActiveTabContent()}</div>

      <div style={{ position: 'absolute', top: '-9999px', left: '-9999px', zIndex: -1 }}>
          <div id="gantt-capture-area" className="bg-white p-8" style={{ width: '1200px' }}>
              <div className="mb-4">
                <h2 className="text-2xl font-bold text-gray-900">{project.name}</h2>
                <p className="text-sm text-gray-500">Cronograma de Proyecto</p>
              </div>
              <GanttChart project={project} tasks={tasks} />
          </div>
      </div>

      {previewFile && (
          <FileViewerModal document={previewFile} user={user} onClose={() => { URL.revokeObjectURL(previewFile.url); setPreviewFile(null); }} />
      )}

      <ConfirmationModal isOpen={isDeleteModalOpen} onClose={() => setDeleteModalOpen(false)} onConfirm={() => onDeleteProject(project.id)} title="Eliminar Proyecto" message={`¿Estás seguro de que quieres eliminar el proyecto "${project.name}"?`} />
      <ConfirmationModal isOpen={isIshikawaConfirmOpen} onClose={() => setIsIshikawaConfirmOpen(false)} onConfirm={() => onSaveProject({...project, ishikawaEnabled: !project.ishikawaEnabled})} title="Ishikawa" message="¿Cambiar visibilidad de Ishikawa?" />
    </>
  );
};

