        title: data.title, 
        projectId: taskData.projectId, 
        status: data.task_status as TaskStatus, 
        startDate: taskData.startDate, 
        duration: taskData.duration, 
        parentId: taskData.parentId,
        assignedTo: data.assigned_to || '',
        comments: data.task_comments || ''
    };
};

