  const searchResultsExt = useMemo(() => !searchQueryExt.trim() ? [] : externalDocuments.filter(doc => doc.name.toLowerCase().includes(searchQueryExt.toLowerCase())), [externalDocuments, searchQueryExt]);
  const folderNameMapExt = useMemo(() => {
