  const handleCancelDeleteLink = () => setLinkToDelete(null);

  const handleOpenAuditModal = (date: string, audit: AuditItem | null) => { setSelectedAuditDate(date); setEditingAudit(audit); setIsAuditModalOpen(true); };
  const handleCloseAuditModal = () => { setIsAuditModalOpen(false); setEditingAudit(null); setSelectedAuditDate(null); };

  const handleSaveAudit = async (auditData: Omit<AuditItem, 'id'>) => {
    try { if (editingAudit) { const savedAudit = await updateAudit({ id: editingAudit.id, ...auditData }); setAudits(audits.map(a => a.id === savedAudit.id ? savedAudit : a)); await addActivity('actualizó la auditoría', `"${savedAudit.title}"`, 'low'); } else { const savedAudit = await addAudit(auditData); setAudits(prev => [savedAudit, ...prev]); await addActivity('programó una nueva auditoría', `"${savedAudit.title}"`, 'medium'); }
    } catch (err) { handleDatabaseError(err, 'Failed to save audit.'); } finally { handleCloseAuditModal(); }
  };
  const handleCloneAudit = async (auditData: Omit<AuditItem, 'id' | 'date'>, dates: string[]) => {
    try { const clonePromises = dates.map(date => { const newAuditData: Omit<AuditItem, 'id'> = { ...auditData, date: date, recurrence: { type: 'none' } }; return addAudit(newAuditData); }); await Promise.all(clonePromises); addToast("Éxito", `Se clonó la auditoría en ${dates.length} fecha(s).`, "success"); await fetchAudits();
    } catch (err) { handleDatabaseError(err, 'Failed to clone audit.'); addToast("Error", "No se pudo clonar la auditoría.", "error"); } finally { handleCloseAuditModal(); }
  };
  const handleDeleteAudit = (auditId: string) => { const audit = audits.find(a => a.id === auditId); if(audit) setAuditToDelete(audit); handleCloseAuditModal(); };
  const handleConfirmDeleteAudit = async () => { if (auditToDelete) { try { await deleteAudit(auditToDelete.id); setAudits(audits.filter(a => a.id !== auditToDelete.id)); await addActivity('eliminó la auditoría', `"${auditToDelete.title}"`, 'high'); } catch(err) { handleDatabaseError(err, 'Failed to delete audit.'); } finally { setAuditToDelete(null); } } };

  const handleSelectProject = (project: Project) => { setSelectedProject(project); };
  const handleSelectProjectById = (projectId: string) => { const project = projects.find(p => p.id === projectId); if (project) { setSelectedProject(project); setActiveView('Proyectos'); } };
  const handleBackToList = () => { setSelectedProject(null); };

  const handleLogin = async (email: string, password: string) => {
    setIsLoading(true); setError(null);
    try { await signIn(email, password); } catch (err) { handleDatabaseError(err, 'Ocurrió un error desconocido durante el inicio de sesión.'); } finally { setIsLoading(false); }
  };

  const handleLogout = async () => { try { await signOut(); } catch (err) { handleDatabaseError(err, 'Ocurrió un error al cerrar la sesión.'); } };

  const handleUpdateAvatar = async (file: File) => {
    if (!user) return;
    setIsAvatarLoading(true); setError(null);
    try { const newAvatarUrl = await updateAvatar(file); setUser(prevUser => { if (!prevUser) return null; return { ...prevUser, avatarUrl: newAvatarUrl }; }); await addActivity('actualizó su foto de perfil', '', 'low');
    } catch (err) { handleDatabaseError(err, 'No se pudo actualizar la foto de perfil.'); } finally { setIsAvatarLoading(false); }
  };

  const changeView = (view: string) => { setSelectedProject(null); setActiveView(view); if (view !== 'Contraseñas') setIsMasterBypassActive(false); };

  if (activeGame) { const game = games[activeGame]; return <GamePlayer onExit={handleGameExit} gameTitle={game.title} gameUrl={game.url} />; }
  if (authLoading) { return ( <div className="min-h-screen flex items-center justify-center bg-dark-bg"> <Spinner /> <span className="ml-4 text-lg text-dark-text">Autenticando...</span> </div> ); }

  if (!user) { return ( <> <LoginView onLogin={handleLogin} isLoading={isLoading} error={error} /> <FloatingRecorder recordingStatus={recordingStatus} recordingTime={recordingTime} uploadStatus={uploadStatus} uploadMessage={uploadMessage} onStartRecording={startRecording} onTogglePauseResume={togglePauseResume} onStopRecording={stopRecording} /> </> ); }
  const renderActiveView = () => {
    const globalErrorDisplay = error ? ( <div className="p-4 mb-4 bg-red-100 border border-red-400 text-red-700 rounded-lg animate-fade-in"> <h3 className="font-bold">Ocurrió un error</h3> <p>{error}</p> <button onClick={() => setError(null)} className="mt-2 text-sm font-semibold underline">Descartar</button> </div> ) : null;
    switch (activeView) {
      case 'Dashboard': return <>{globalErrorDisplay}<DashboardView projects={projects} audits={audits} activities={activities.slice(0, 5)} tasks={tasks} onSelectProject={handleSelectProjectById} /></>;
      case 'Proyectos':
        if (selectedProject) { return <>{globalErrorDisplay}<ProjectDetailView project={selectedProject} tasks={tasks.filter(t => t.projectId === selectedProject.id)} documents={documents} folders={folders} onBackToList={handleBackToList} onDeleteProject={handleDeleteProject} onSaveProject={handleSaveProject} onAddTask={handleAddTask} onToggleTask={handleToggleTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} onAddDocument={handleAddDocument} onDeleteDocument={handleDeleteDocument} userPermissions={userPermissions} user={user!} /></>; }
        return <>{globalErrorDisplay}<ProjectsListView projects={projects} tasks={tasks} isLoading={(projectsLoading || tasksLoading) && projects.length === 0} onSelectProject={handleSelectProject} onSaveProject={handleSaveProject} onUpdateProjectStatus={handleUpdateProjectStatus} onError={handleDatabaseError} geminiApiKey={geminiApiKey} userPermissions={userPermissions} /></>;
      case 'Documentos': return <>{globalErrorDisplay}<DocumentsView projects={projects} folders={folders} documents={documents} externalFolders={externalFolders} externalDocuments={externalDocuments} isLoading={foldersLoading || documentsLoading} onAddFolder={handleAddFolder} onDeleteFolder={handleDeleteFolder} onAddDocument={handleAddDocument} onDeleteDocument={handleDeleteDocument} onAddExternalFolder={handleAddExternalFolder} onDeleteExternalFolder={handleDeleteExternalFolder} onAddExternalDocument={handleAddExternalDocument} onDeleteExternalDocument={handleDeleteExternalDocument} userPermissions={userPermissions} user={user!} /></>;
      case 'Enlaces': return <>{globalErrorDisplay}<LinksView links={links} isLoading={linksLoading} onOpenLinkModal={handleOpenLinkModal} onOpenEditLinkModal={handleOpenEditLinkModal} onDeleteLink={handleDeleteLink} userPermissions={userPermissions} /></>;
      case 'Apps': return <>{globalErrorDisplay}<AppsView /></>;
      case 'CODEX': return <>{globalErrorDisplay}<NexusView documents={documents} folders={folders} externalDocuments={externalDocuments} externalFolders={externalFolders} /></>;
      case 'Auditorias': return <>{globalErrorDisplay}<AuditsView audits={audits} onOpenModal={handleOpenAuditModal} userPermissions={userPermissions} /></>;
      case 'Pizarra': return <>{globalErrorDisplay}<WhiteboardView userPermissions={userPermissions} />;</>;
      case 'Bitácora': return <>{globalErrorDisplay}<VoiceLogView /></>;
      case 'Notificaciones': return <>{globalErrorDisplay}<NotificationsView notifications={activities} readNotificationIds={readNotificationIds} onMarkAsRead={markAsRead} onMarkAllAsRead={markAllAsRead} onNavigate={changeView} /></>;
      case 'Contraseñas': return <>{globalErrorDisplay}<PasswordsView userPermissions={userPermissions} isMasterBypassActive={isMasterBypassActive} /></>;
      case 'Juegos': return <>{globalErrorDisplay}<GamesView onEnterGame={handleGameEnter} /></>;
      case 'Administrador':
        const allowedAdmins = ['darienperez695@gmail.com', 'zerklucio@gmail.com'];
        if (!user || !allowedAdmins.includes((user.username || '').toLowerCase().trim())) { return <>{globalErrorDisplay}<DashboardView projects={projects} audits={audits} activities={activities.slice(0, 5)} tasks={tasks} onSelectProject={handleSelectProjectById} /></>; }
        return <>{globalErrorDisplay}<AdminView /> </>;
      default: return <>{globalErrorDisplay}<DashboardView projects={projects} audits={audits} activities={activities.slice(0, 5)} tasks={tasks} onSelectProject={handleSelectProjectById} /></>;
    }
  };

  return (
    <div className="flex h-screen bg-light-bg text-light-text dark:bg-dark-bg dark:text-dark-text font-sans">
      <ToastContainer notifications={toastNotifications} onDismiss={removeToast} />
      <Sidebar isOpen={true} activeView={activeView} setActiveView={changeView} currentTheme={theme} onThemeChange={handleThemeChange} onSecretTrigger={handleSecretTrigger} onSecretSequenceStep={handleSecretSequenceStep} onHideGamesTrigger={handleHideGamesTrigger} isGamesSectionUnlocked={isGamesSectionUnlocked} recordingStatus={recordingStatus} recordingTime={recordingTime} uploadStatus={uploadStatus} uploadMessage={uploadMessage} onStartRecording={startRecording} onTogglePauseResume={togglePauseResume} onStopRecording={stopRecording} user={user} userPermissions={userPermissions} setIsMasterBypassActive={setIsMasterBypassActive} />
      <div className={`flex-1 flex flex-col transition-all duration-300 ml-64 overflow-x-hidden`}>
        <Header user={user!} onUpdateAvatar={handleUpdateAvatar} isAvatarLoading={isAvatarLoading} onLogout={handleLogout} unreadCount={unreadCount} notifications={activities} readNotificationIds={readNotificationIds} onMarkAsRead={markAsRead} onNavigate={changeView} onMarkAllAsRead={markAllAsRead} recordingStatus={recordingStatus} recordingTime={recordingTime} isEditor={true} />
        <main className="flex-1 p-6 lg:p-8 overflow-y-auto"> <div className="animate-fade-in"> {renderActiveView()} </div> </main>
      </div>
      {isCodeModalVisible && ( <SecretCodeModal onClose={() => { setIsCodeModalVisible(false); setSecretSequence([]); }} onSubmit={handleCodeSubmit} /> )}
      {isLinkModalOpen && ( <LinkModal onClose={handleCloseLinkModal} onSave={handleSaveLink} linkToEdit={linkToEdit} /> )}
      {linkToDelete && ( <ConfirmationModal isOpen={!!linkToDelete} onClose={handleCancelDeleteLink} onConfirm={handleConfirmDeleteLink} title="Eliminar Enlace" message={`¿Estás seguro de que quieres eliminar el enlace "${linkToDelete.name}"? Esta acción no se puede deshacer.`} /> )}
      {isAuditModalOpen && selectedAuditDate && ( <AuditModal audit={editingAudit} date={selectedAuditDate} onClose={handleCloseAuditModal} onSave={handleSaveAudit as any} onDelete={handleDeleteAudit} onClone={handleCloneAudit} isReadOnly={!userPermissions?.auditorias.canManage} /> )}
      {auditToDelete && ( <ConfirmationModal isOpen={!!auditToDelete} onClose={() => setAuditToDelete(null)} onConfirm={handleConfirmDeleteAudit} title="Eliminar Auditoría" message={`¿Estás seguro de que quieres eliminar la auditoría "${auditToDelete.title}"? Esta acción no se puede deshacer.`} /> )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { ChartPieIcon, ClipboardListIcon, CogIcon, DocumentTextIcon, FolderOpenIcon, HomeIcon, LinkIcon, PencilAltIcon, SparklesIcon, UsersIcon, BellIcon, CustomLogoIcon, SunIcon, MoonIcon, ColorSwatchIcon, CheckCircleIcon, XCircleIcon, GameControllerIcon, KeyIcon, ViewGridIcon, AcademicCapIcon, MicrophoneIcon } from './Icons';
import Spinner from './Spinner';
import { User, UserPermissions } from '../types';

type RecordingStatus = 'idle' | 'recording' | 'paused';
type UploadStatus = 'idle' | 'uploading' | 'success' | 'error';

interface SidebarProps {
    isOpen: boolean;
    activeView: string;
    setActiveView: (view: string) => void;
    currentTheme: string;
    onThemeChange: (themeName: string, customColors?: Record<string, string> | null) => void;
    onSecretTrigger: () => void;
    onSecretSequenceStep: (step: string) => void;
    onHideGamesTrigger: () => void;
    isGamesSectionUnlocked: boolean;
    recordingStatus: RecordingStatus;
    recordingTime: number;
    uploadStatus: UploadStatus;
    uploadMessage: string;
    onStartRecording: () => void;
    onTogglePauseResume: () => void;
    onStopRecording: () => void;
    user: User;
    userPermissions: UserPermissions | null;
    setIsMasterBypassActive: (isActive: boolean) => void;
}

const NavLink: React.FC<{ 
    icon: React.ReactNode; 
    text: string; 
    isOpen: boolean; 
    isActive: boolean;
    onClick: () => void;
    onMouseDown?: () => void;
    onMouseUp?: () => void;
    onMouseLeave?: () => void;
    onTouchStart?: () => void;
    onTouchEnd?: () => void;
}> = ({ icon, text, isOpen, isActive, onClick, ...longPressProps }) => (
    <a 
      href="#" 
      onClick={(e) => { e.preventDefault(); onClick(); }}
      className={`flex items-center p-3 my-1 rounded-lg transition-colors duration-200 text-white ${isActive ? 'bg-[var(--color-brand-secondary)] font-semibold' : 'hover:bg-[var(--color-brand-secondary)]/50'}`}
      title={text}
      {...longPressProps}
    >
        {icon}
        <span className={`ml-4 whitespace-nowrap transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>{text}</span>
    </a>
);

const Sidebar: React.FC<SidebarProps> = ({ 
    isOpen, activeView, setActiveView, currentTheme, onThemeChange, onSecretTrigger,
    onSecretSequenceStep, onHideGamesTrigger, isGamesSectionUnlocked,
    recordingStatus, recordingTime, uploadStatus, uploadMessage,
    onStartRecording, onTogglePauseResume, onStopRecording,
    user, userPermissions, setIsMasterBypassActive
}) => {
    const [isCustomizerOpen, setCustomizerOpen] = useState(false);
    const longPressTimer = useRef<ReturnType<typeof setTimeout>>();

    const handlePasswordLongPressStart = () => {
        longPressTimer.current = window.setTimeout(() => {
            setIsMasterBypassActive(true);
            setActiveView('Contraseñas');
        }, 6000); // 6 seconds
    };

    const handlePasswordLongPressEnd = () => {
        clearTimeout(longPressTimer.current);
    };


    const defaultCustomColors = {
        '--color-brand-primary': '#4a90e2',
        '--color-brand-secondary': '#357abd',
        '--color-light-bg': '#f0f2f5',
        '--color-dark-bg': '#1c1c1e',
        '--color-light-card': '#ffffff',
        '--color-dark-card': '#2c2c2e',
        '--color-light-text': '#111827',
        '--color-light-text-secondary': '#6b7280',
        '--color-dark-text': '#c9d1d9',
        '--color-dark-text-secondary': '#8b949e',
    };
    const [customColors, setCustomColors] = useState(defaultCustomColors);

    const interfaceColorKeys = [
        '--color-brand-primary', '--color-brand-secondary', '--color-light-bg', 
        '--color-dark-bg', '--color-light-card', '--color-dark-card'
    ];
    const textColorKeys = [
        '--color-light-text', '--color-light-text-secondary', 
        '--color-dark-text', '--color-dark-text-secondary'
    ];

    const handleColorChange = (key: string, value: string) => {
        const newColors = { ...customColors, [key]: value };
        setCustomColors(newColors);
        if (currentTheme === 'custom') {
            onThemeChange('custom', newColors);
        }
    };

    const handleSaveCustomTheme = () => {
        onThemeChange('custom', customColors);
        setCustomizerOpen(false);
    };

    const [isControlsVisible, setIsControlsVisible] = useState(false);
    const [showToast, setShowToast] = useState(false);

    useEffect(() => {
        if (uploadStatus !== 'idle') {
        setShowToast(true);
        const timer = setTimeout(() => {
            setShowToast(false);
        }, 4000); 
        return () => clearTimeout(timer);
        }
    }, [uploadStatus]);

    const handleDoubleClick = () => {
        if (recordingStatus === 'idle' || isControlsVisible) {
        setIsControlsVisible(prev => !prev);
        }
    };

    const handleStopAndSave = () => {
        onStopRecording();
        setIsControlsVisible(false); 
    };

    const renderToast = () => {
        let icon, bgColor, textColor;
        switch (uploadStatus) {
            case 'uploading': icon = <Spinner />; bgColor = 'bg-blue-500'; textColor = 'text-white'; break;
            case 'success': icon = <CheckCircleIcon className="h-6 w-6" />; bgColor = 'bg-green-500'; textColor = 'text-white'; break;
            case 'error': icon = <XCircleIcon className="h-6 w-6" />; bgColor = 'bg-red-500'; textColor = 'text-white'; break;
            default: return null;
        }
        return (
            <div className={`flex items-center gap-3 p-3 rounded-lg shadow-lg ${bgColor} ${textColor}`}>
                {icon}
                <span className="text-sm font-medium">{uploadMessage}</span>
            </div>
        );
    };

    const navItems = [
        { name: 'Dashboard', icon: <HomeIcon className="h-6 w-6"/>, id: 'dashboard' },
        { name: 'Proyectos', icon: <FolderOpenIcon className="h-6 w-6"/>, id: 'proyectos' },
        { name: 'Documentos', icon: <DocumentTextIcon className="h-6 w-6"/>, id: 'documentos' },
        { name: 'Enlaces', icon: <LinkIcon className="h-6 w-6"/>, id: 'enlaces' },
        { name: 'Apps', icon: <ViewGridIcon className="h-6 w-6"/>, id: 'apps' },
        { name: 'CODEX', icon: <AcademicCapIcon className="h-6 w-6"/>, id: 'codex' }, // RENAMED FROM NEXUS
        { name: 'Auditorias', icon: <ClipboardListIcon className="h-6 w-6"/>, id: 'auditorias' },
        { name: 'Pizarra', icon: <PencilAltIcon className="h-6 w-6"/>, id: 'pizarra' },
        { name: 'Bitácora', icon: <MicrophoneIcon className="h-6 w-6"/>, id: 'bitacora' },
        { name: 'Notificaciones', icon: <BellIcon className="h-6 w-6"/>, id: 'notificaciones' },
        { name: 'Contraseñas', icon: <KeyIcon className="h-6 w-6"/>, id: 'contraseñas' },
    ];

    const visibleNavItems = useMemo(() => {
        const sidebarPermissions = userPermissions?.sidebar;
        if (!sidebarPermissions) {
            return navItems; 
        }
        return navItems.filter(item => {
            const permKey = item.id as keyof typeof sidebarPermissions;
            return sidebarPermissions[permKey];
        });
    }, [userPermissions, navItems]);


    return (
        <>
            <aside className={`fixed top-0 left-0 h-full bg-brand-primary shadow-lg z-30 transition-all duration-300 flex flex-col ${isOpen ? 'w-64' : 'w-20'}`}>
                <div className={`relative flex items-center h-16 border-b border-[var(--color-brand-secondary)]/50 flex-shrink-0 ${isOpen ? 'px-4 justify-start' : 'justify-center'}`}>
                    <div className={`flex items-center transition-all duration-300`}>
                        <div onClick={onSecretTrigger} className="cursor-default" aria-hidden="true">
                            <CustomLogoIcon className="h-8 w-8 text-white" />
                        </div>
                        <h1 className={`text-xl font-bold text-white ml-2 whitespace-nowrap transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0'}`}>Interfaz M.C</h1>
                    </div>
                </div>
                <nav className="flex-1 p-3 overflow-y-auto">
                    {visibleNavItems.map(item => {
                        const isPasswords = item.name === 'Contraseñas';
                        return (
                            <NavLink 
                                key={item.name}
                                icon={item.icon} 
                                text={item.name} 
                                isOpen={isOpen}
                                isActive={activeView === item.name}
                                onClick={() => {
                                    setActiveView(item.name);
                                    if (item.name === 'Pizarra') onSecretSequenceStep('pizarra');
                                    if (item.name === 'Notificaciones') onSecretSequenceStep('notificaciones');
                                }}
                                onMouseDown={isPasswords ? handlePasswordLongPressStart : undefined}
                                onMouseUp={isPasswords ? handlePasswordLongPressEnd : undefined}
                                onMouseLeave={isPasswords ? handlePasswordLongPressEnd : undefined}
                                onTouchStart={isPasswords ? handlePasswordLongPressStart : undefined}
                                onTouchEnd={isPasswords ? handlePasswordLongPressEnd : undefined}
                            />
                        );
                    })}
                    {isGamesSectionUnlocked && (
                        <NavLink 
                            key="Juegos"
                            icon={<GameControllerIcon className="h-6 w-6"/>}
                            text="Juegos"
                            isOpen={isOpen}
                            isActive={activeView === 'Juegos'}
                            onClick={() => setActiveView('Juegos')}
                        />
                    )}
                    {['darienperez695@gmail.com', 'zerklucio@gmail.com'].includes((user.username || '').toLowerCase().trim()) && (
                        <NavLink 
                            key="Administrador"
                            icon={<CogIcon className="h-6 w-6"/>}
                            text="Administrador"
                            isOpen={isOpen}
                            isActive={activeView === 'Administrador'}
                            onClick={() => setActiveView('Administrador')}
                        />
                    )}
                </nav>

                <div className="p-3 mb-2">
                    <div className="flex flex-col items-center gap-2">
                        <div className={`transition-all duration-300 ${showToast ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
                            {renderToast()}
                        </div>

                        <div className={`flex w-48 h-8 rounded-full overflow-hidden shadow-lg border border-black/20 transition-all duration-300 ${isControlsVisible ? 'opacity-100 scale-100' : 'opacity-0 scale-90 pointer-events-none'}`} role="group">
                            <button onClick={onStartRecording} disabled={recordingStatus !== 'idle'} className={`w-1/3 bg-green-500 hover:bg-green-600 disabled:bg-gray-400 transition-colors ${recordingStatus === 'recording' ? 'animate-subtle-pulse' : ''}`} title="Grabar" aria-label="Iniciar Grabación"/>
                            <button onClick={onTogglePauseResume} disabled={recordingStatus === 'idle'} className="w-1/3 bg-sky-500 hover:bg-sky-600 disabled:bg-gray-400 transition-colors" title="Pausar/Reanudar" aria-label="Pausar o Reanudar Grabación"/>
                            <button onClick={handleStopAndSave} disabled={recordingStatus === 'idle'} className="w-1/3 bg-blue-800 hover:bg-blue-900 disabled:bg-gray-400 transition-colors" title="Detener y Guardar" aria-label="Detener y Guardar Grabación"/>
                        </div>

                        <button
                            onDoubleClick={handleDoubleClick}
                            className="w-8 h-8 rounded-full flex items-center justify-center shadow-md transition-colors text-gray-800 bg-white hover:bg-gray-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-brand-primary dark:focus:ring-offset-dark-card"
                            aria-label="Doble clic para mostrar/ocultar grabadora"
                        >
                        </button>
                    </div>
                </div>

                <div className="p-3 border-t border-[var(--color-brand-secondary)]/50 relative">
                    <div className="flex items-center justify-around">
                        <button onClick={() => onThemeChange('light')} title="Tema Claro" className={`p-2 rounded-full ${currentTheme === 'light' ? 'bg-white/30' : 'hover:bg-white/20'}`}>
                            <SunIcon className="h-5 w-5 text-white" />
                        </button>
                        <button onClick={() => onThemeChange('dark')} title="Tema Oscuro" className={`p-2 rounded-full ${currentTheme === 'dark' ? 'bg-white/30' : 'hover:bg-white/20'}`}>
                            <MoonIcon className="h-5 w-5 text-white" />
                        </button>
                        <button onClick={() => setCustomizerOpen(!isCustomizerOpen)} title="Personalizar Tema" className={`p-2 rounded-full ${currentTheme === 'custom' ? 'bg-white/30' : 'hover:bg-white/20'}`}>
                            <ColorSwatchIcon className="h-5 w-5 text-white" />
                        </button>
                    </div>
                    {isCustomizerOpen && (
                        <div className={`absolute bottom-full mb-2 p-4 bg-light-card dark:bg-dark-card rounded-lg shadow-2xl border border-light-border dark:border-dark-border ${isOpen ? 'left-4 right-4' : 'left-full ml-2 w-72'}`}>
                            <h4 className="text-sm font-bold text-light-text dark:text-dark-text mb-3">Personalizar Tema</h4>

                            <div className="space-y-3">
                                <div>
                                    <p className="text-xs font-semibold text-light-text-secondary dark:text-dark-text-secondary mb-2 uppercase tracking-wider">Colores de Interfaz</p>
                                    <div className="space-y-2">
                                        {interfaceColorKeys.map(key => (
                                            <div key={key} className="flex items-center justify-between text-xs text-light-text-secondary dark:text-dark-text-secondary capitalize">
                                                <label htmlFor={key}>{key.replace('--color-', '').replace(/-/g, ' ')}</label>
                                                <input
                                                    type="color"
                                                    id={key}
                                                    value={customColors[key as keyof typeof customColors]}
                                                    onChange={(e) => handleColorChange(key, e.target.value)}
                                                    className="w-8 h-6 p-0 border-none rounded cursor-pointer bg-transparent"
                                                />
                                            </div>
                                        ))}
                                    </div>
                                </div>

                                <div>
                                    <p className="text-xs font-semibold text-light-text-secondary dark:text-dark-text-secondary mb-2 uppercase tracking-wider">Colores de Texto</p>
                                    <div className="space-y-2">
                                        {textColorKeys.map(key => (
                                            <div key={key} className="flex items-center justify-between text-xs text-light-text-secondary dark:text-dark-text-secondary capitalize">
                                                <label htmlFor={key}>{key.replace('--color-', '').replace(/-/g, ' ')}</label>
                                                <input
                                                    type="color"
                                                    id={key}
                                                    value={customColors[key as keyof typeof customColors]}
                                                    onChange={(e) => handleColorChange(key, e.target.value)}
                                                    className="w-8 h-6 p-0 border-none rounded cursor-pointer bg-transparent"
                                                />
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <button onClick={handleSaveCustomTheme} className="w-full mt-4 px-3 py-1.5 text-xs font-semibold text-white bg-brand-primary rounded-md hover:bg-brand-secondary">
                                Aplicar y Guardar
                            </button>
                        </div>
                    )}
                </div>

                <div className="p-4 flex-shrink-0">
                    <p 
                      onClick={() => {
                        onSecretSequenceStep('footer');
                        onHideGamesTrigger();
                      }} 
                      className={`text-xs text-center text-white/70 transition-opacity duration-300 cursor-pointer ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
                    >
                        SUAVE Y FACIL S.A. de C.V.
                    </p>
                </div>
            </aside>
        </>
    );
};

export default Sidebar;

import React, { useState, useEffect, useMemo } from 'react';
import { 
    ServerIcon, 
    FolderIcon, 
    DocumentTextIcon, 
    SearchIcon, 
    ArrowLeftIcon, 
    GlobeAltIcon, 
    XCircleIcon, 
    InformationCircleIcon, 
    RefreshIcon,
    TerminalIcon,
    CogIcon 
} from '../components/Icons';
import { Document as AppDocument, PublishedProcedure, Folder, PublishedFolder } from '../types';
import { 
    getLocalPublishedProcedures, 
    getExternalPublishedProcedures, 
    publishLocalProcedure, 
    publishExternalProcedure, 
    unpublishLocalProcedure, 
    unpublishExternalProcedure,
    getLocalPublishedFolders,
    getExternalPublishedFolders,
    publishLocalFolder,
    publishExternalFolder,
    unpublishLocalFolder,
    unpublishExternalFolder,
    getDepartments
} from '../services/supabaseService';

interface NexusViewProps {
    documents: AppDocument[];
    externalDocuments: AppDocument[];
    folders: Folder[];
    externalFolders: Folder[];
}

const SCANLINE_BG = `url("data:image/svg+xml,%3Csvg width='40' height='40' viewBox='0 0 40 40' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0 20h40' stroke='%23ffffff' stroke-opacity='0.03' fill='none'/%3E%3C/svg%3E")`;

const NexusView: React.FC<NexusViewProps> = ({ documents, externalDocuments, folders, externalFolders }) => {
    // --- STATE MANAGEMENT ---

    const [activeDb, setActiveDb] = useState<'local' | 'external'>('local');
    const [currentPath, setCurrentPath] = useState<Folder[]>([]); 
    const [selectedItem, setSelectedItem] = useState<AppDocument | null>(null);
    const [selectedFolder, setSelectedFolder] = useState<Folder | null>(null); 

    const [publishedList, setPublishedList] = useState<PublishedProcedure[]>([]);
    const [publishedFoldersList, setPublishedFoldersList] = useState<PublishedFolder[]>([]); 
    const [isLoading, setIsLoading] = useState(false);
    const [isProcessing, setIsProcessing] = useState(false);

    const [areas, setAreas] = useState<string[]>([]);
    const [isLoadingAreas, setIsLoadingAreas] = useState(true);

    const [searchTerm, setSearchTerm] = useState('');
    const [publishForm, setPublishForm] = useState({ code: '', area: '', version: '1.0', status: 'Vigente' });
    const [statusMessage, setStatusMessage] = useState<{ text: string, type: 'success' | 'error' | 'info' } | null>(null);

    const currentThemeColor = activeDb === 'local' ? 'cyan' : 'fuchsia';

    const activeDocs = activeDb === 'local' ? documents : externalDocuments;
    const activeFolders = activeDb === 'local' ? folders : externalFolders;

    const refreshData = async () => {
        setIsLoading(true);
        try {
            const [localPubs, extPubs, localFolders, extFolders] = await Promise.all([
                getLocalPublishedProcedures(),
                getExternalPublishedProcedures(),
                getLocalPublishedFolders(),
                getExternalPublishedFolders()
            ]);

            if (activeDb === 'local') {
                setPublishedList(localPubs);
                setPublishedFoldersList(localFolders);
            } else {
                setPublishedList(extPubs);
                setPublishedFoldersList(extFolders);
            }
        } catch (err) {
            console.error("Codex Sync Error:", err);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        refreshData();
    }, [activeDb]);

    useEffect(() => {
        const loadAreas = async () => {
            setIsLoadingAreas(true);
            try {
                const depNames = await getDepartments();
                setAreas(depNames);
                if (depNames.length > 0 && !publishForm.area) {
                    setPublishForm(prev => ({...prev, area: depNames[0]}));
                }
            } catch (error) {
                console.error("Failed to load departments:", error);
            } finally {
                setIsLoadingAreas(false);
            }
        };
        loadAreas();
    }, []);

    const currentFolderId = currentPath.length > 0 ? currentPath[currentPath.length - 1].id : null;

    useEffect(() => {
        if (currentPath.length === 0 && activeFolders.length > 0) {
            const general = activeFolders.find(f => f.name === 'General');
            if (general) setCurrentPath([general]);
        }
    }, [activeFolders, activeDb]);

    const handleNavigate = (folder: Folder) => {
        setCurrentPath([...currentPath, folder]);
        setSelectedItem(null); 
        setSelectedFolder(null);
        setSearchTerm('');
    };

    const handleNavigateUp = () => {
        if (currentPath.length > 0) {
            setCurrentPath(currentPath.slice(0, -1));
            setSelectedItem(null);
            setSelectedFolder(null);
        }
    };

    const handleBreadcrumbClick = (index: number) => {
        setCurrentPath(currentPath.slice(0, index + 1));
        setSelectedItem(null);
        setSelectedFolder(null);
    };

    const displayedItems = useMemo(() => {
        let docs = activeDocs;
        let subFolders = activeFolders;

        if (searchTerm.trim()) {
            return {
                folders: [],
                files: docs.filter(d => d.name.toLowerCase().includes(searchTerm.toLowerCase()))
            };
        } else {
            if (currentFolderId) {
                docs = docs.filter(d => d.folderId === currentFolderId);
                subFolders = subFolders.filter(f => f.parentId === currentFolderId);
            } else {
                docs = docs.filter(d => !d.folderId);
                subFolders = subFolders.filter(f => !f.parentId);
            }
            return { folders: subFolders, files: docs };
        }
    }, [activeDocs, activeFolders, currentFolderId, searchTerm]);

    const handleSelectItem = (doc: AppDocument) => {
        setSelectedItem(doc);
        setSelectedFolder(null); 

        const publishedInfo = publishedList.find(p => p.uad_origin_id === doc.id);

        if (publishedInfo) {
            setPublishForm({
                code: publishedInfo.code,
                area: publishedInfo.area,
                version: publishedInfo.version,
                status: publishedInfo.status || 'Vigente'
            });
        } else {
            setPublishForm({
                code: '',
                area: areas.length > 0 ? areas[0] : '',
                version: '1.0',
                status: 'Vigente'
            });
        }
        setStatusMessage(null);
    };

    const handleSelectFolder = (e: React.MouseEvent, folder: Folder) => {
        e.stopPropagation();
        setSelectedFolder(folder);
        setSelectedItem(null); 

        const publishedInfo = publishedFoldersList.find(p => p.origin_folder_id === folder.id);

        if (publishedInfo) {
            setPublishForm(prev => ({
                ...prev,
                area: publishedInfo.area,
            }));
        } else {
             setPublishForm(prev => ({
                ...prev,
                area: areas.length > 0 ? areas[0] : '',
            }));
        }
        setStatusMessage(null);
    };

    const handlePublish = async () => {
        setIsProcessing(true);

        try {
            if (selectedItem) {
                setStatusMessage({ text: 'ENLAZANDO DOCUMENTO...', type: 'info' });
                const payload = {
                    title: selectedItem.name,
                    code: publishForm.code,
                    area: publishForm.area,
                    version: publishForm.version,
                    status: publishForm.status,
                    origin_id: selectedItem.id,
                    storage_path: selectedItem.storagePath,
                    folder_id: selectedItem.folderId
                };

                if (activeDb === 'local') await publishLocalProcedure(payload);
                else await publishExternalProcedure(payload);

            } else if (selectedFolder) {
                setStatusMessage({ text: 'ENLAZANDO CARPETA...', type: 'info' });
                if (activeDb === 'local') await publishLocalFolder(selectedFolder.id, selectedFolder.name, publishForm.area);
                else await publishExternalFolder(selectedFolder.id, selectedFolder.name, publishForm.area);
            }

            await refreshData();
            setStatusMessage({ text: 'ENLACE ESTABLECIDO', type: 'success' });
        } catch (err) {
            setStatusMessage({ text: 'FALLÓ LA TRANSMISIÓN', type: 'error' });
            console.error(err);
        } finally {
            setIsProcessing(false);
        }
    };

    const handleUnpublish = async () => {
        setIsProcessing(true);
        setStatusMessage({ text: 'TERMINANDO CONEXIÓN...', type: 'info' });

        try {
            if (selectedItem) {
                const pubRecord = publishedList.find(p => p.uad_origin_id === selectedItem.id);
                if (pubRecord) {
                    if (activeDb === 'local') await unpublishLocalProcedure(pubRecord.id);
                    else await unpublishExternalProcedure(pubRecord.id);
                }
            } else if (selectedFolder) {
                if (activeDb === 'local') await unpublishLocalFolder(selectedFolder.id);
                else await unpublishExternalFolder(selectedFolder.id);
            }

            await refreshData();
            setStatusMessage({ text: 'OBJETIVO DESVINCULADO', type: 'success' });
            setPublishForm(prev => ({ ...prev, code: '', version: '1.0', status: 'Vigente' }));
        } catch (err) {
            setStatusMessage({ text: 'FALLÓ LA TERMINACIÓN', type: 'error' });
        } finally {
            setIsProcessing(false);
        }
    };

    const isFolderPublished = selectedFolder ? publishedFoldersList.some(p => p.origin_folder_id === selectedFolder.id) : false;
    const isFilePublished = selectedItem ? publishedList.some(p => p.uad_origin_id === selectedItem.id) : false;
    const isCurrentPublished = selectedFolder ? isFolderPublished : isFilePublished;

    return (
        <div className="flex flex-col h-[calc(100vh-6rem)] bg-[#050b14] text-slate-300 font-sans overflow-hidden rounded-xl border border-slate-800 shadow-2xl relative">
            <div className="absolute inset-0 pointer-events-none z-0" style={{ backgroundImage: SCANLINE_BG }}></div>

            <header className="relative z-10 flex items-center justify-between p-4 bg-slate-900/80 backdrop-blur-md border-b border-slate-700">
                <div className="flex items-center gap-4">
                    <div className={`p-2 rounded border border-${currentThemeColor}-500/30 bg-${currentThemeColor}-500/10`}>
                        <GlobeAltIcon className={`h-6 w-6 text-${currentThemeColor}-400`} />
                    </div>
                    <div>
                        <h1 className="text-xl font-extrabold tracking-wider text-white uppercase flex items-center gap-2">
                            CODEX <span className={`text-${currentThemeColor}-400`}>//</span> ENLACE
                        </h1>
                        <p className="text-[10px] uppercase tracking-[0.2em] text-slate-500 font-bold">Interfaz de Puente de Datos Seguro</p>
                    </div>
                </div>

                <div className="flex items-center bg-black/50 rounded-full p-1 border border-slate-700">
                    <button
                        onClick={() => setActiveDb('local')}
                        className={`px-4 py-1.5 rounded-full text-xs font-bold tracking-widest transition-all duration-300 uppercase ${
                            activeDb === 'local' 
                            ? 'bg-cyan-500 text-black shadow-[0_0_15px_rgba(6,182,212,0.5)]' 
                            : 'text-slate-500 hover:text-cyan-400'
                        }`}
                    >
                        BD_LOCAL
                    </button>
                    <button
                        onClick={() => setActiveDb('external')}
                        className={`px-4 py-1.5 rounded-full text-xs font-bold tracking-widest transition-all duration-300 uppercase ${
                            activeDb === 'external' 
                            ? 'bg-fuchsia-500 text-black shadow-[0_0_15px_rgba(217,70,239,0.5)]' 
                            : 'text-slate-500 hover:text-fuchsia-400'
                        }`}
                    >
                        BD_REMOTA
                    </button>
                </div>

                <div className="relative group">
                    <input 
                        type="text" 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        placeholder="ESCANEAR DATOS..."
                        className={`bg-slate-900 border border-slate-700 text-${currentThemeColor}-400 text-xs font-bold uppercase py-2 pl-9 pr-4 rounded w-48 focus:w-64 transition-all focus:outline-none focus:border-${currentThemeColor}-500 focus:shadow-[0_0_10px_rgba(0,0,0,0.5)]`}
                    />
                    <SearchIcon className="absolute left-3 top-2.5 h-3.5 w-3.5 text-slate-600 group-focus-within:text-white transition-colors" />
                </div>
            </header>

            <div className="flex flex-1 relative z-10 overflow-hidden">

                <section className="flex-1 flex flex-col border-r border-slate-800 bg-slate-900/30">
                    <div className="flex items-center gap-2 p-3 text-xs font-bold uppercase border-b border-slate-800/50 bg-black/20 text-slate-400 overflow-x-auto">
                        <span 
                            onClick={() => setCurrentPath([])} 
                            className="cursor-pointer hover:text-white flex items-center gap-1"
                        >
                            <ServerIcon className="h-3 w-3" /> RAÍZ
                        </span>
                        {currentPath.map((folder, idx) => (
                            <React.Fragment key={folder.id}>
                                <span className="text-slate-600">/</span>
                                <span 
                                    onClick={() => handleBreadcrumbClick(idx)}
                                    className={`cursor-pointer hover:text-white whitespace-nowrap ${idx === currentPath.length - 1 ? `text-${currentThemeColor}-400 font-extrabold` : ''}`}
                                >
                                    {folder.name.toUpperCase()}
                                </span>
                            </React.Fragment>
                        ))}
                    </div>

                    <div className="flex-1 p-4 overflow-y-auto custom-scrollbar">
                        {searchTerm ? (
                            <div className="text-xs font-bold text-slate-500 mb-4 uppercase tracking-wide"> Resultados de Búsqueda :: {displayedItems.files.length} encontrados</div>
                        ) : null}

                        {currentPath.length > 0 && !searchTerm && (
                            <div 
                                onClick={handleNavigateUp}
                                className="inline-flex items-center gap-2 px-4 py-3 mb-4 rounded border border-slate-700 bg-slate-800/50 hover:bg-slate-700/50 cursor-pointer transition-colors text-slate-300 text-xs font-bold uppercase"
                            >
                                <ArrowLeftIcon className="h-4 w-4" />
                                ../VOLVER
                            </div>
                        )}

                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                            {displayedItems.folders.map(folder => {
                                const isPublished = publishedFoldersList.some(p => p.origin_folder_id === folder.id);
                                const isSelected = selectedFolder?.id === folder.id;

                                return (
                                <div 
                                    key={folder.id}
                                    onClick={() => handleNavigate(folder)}
                                    className={`
                                        group relative p-4 rounded bg-slate-800/40 border 
                                        ${isSelected ? `border-${currentThemeColor}-500 bg-${currentThemeColor}-900/20` : 'border-slate-700/50'}
                                        hover:border-${currentThemeColor}-500/50 hover:bg-${currentThemeColor}-500/10 hover:shadow-[0_0_15px_rgba(0,0,0,0.3)]
                                        cursor-pointer transition-all duration-200 flex flex-col items-center gap-3
                                    `}
                                >
                                    <div className="relative">
                                        <FolderIcon className={`h-8 w-8 ${isSelected ? `text-${currentThemeColor}-400` : 'text-slate-500'} group-hover:text-${currentThemeColor}-400 transition-colors`} />
                                        {isPublished && (
                                            <div className="absolute -top-1 -right-1 flex h-2.5 w-2.5">
                                                <span className={`animate-ping absolute inline-flex h-full w-full rounded-full bg-${currentThemeColor}-400 opacity-75`}></span>
                                                <span className={`relative inline-flex rounded-full h-2.5 w-2.5 bg-${currentThemeColor}-500`}></span>
                                            </div>
                                        )}
                                    </div>
                                    <span className={`text-xs font-bold uppercase truncate w-full text-center tracking-wide ${isSelected ? 'text-white' : 'text-slate-300'}`}>{folder.name}</span>

                                    <button 
                                        onClick={(e) => handleSelectFolder(e, folder)}
                                        className={`absolute top-2 right-2 p-1 rounded-full hover:bg-black/50 text-slate-500 hover:text-${currentThemeColor}-400 transition-colors z-10`}
                                        title="Configurar Carpeta"
                                    >
                                        <CogIcon className="h-4 w-4" />
                                    </button>

                                    <div className={`absolute bottom-0 left-0 w-2 h-2 border-b border-l border-${currentThemeColor}-500 opacity-0 group-hover:opacity-100 transition-opacity`}></div>
                                </div>
                            )})}

                            {displayedItems.files.map(doc => {
                                const isPublished = publishedList.some(p => p.uad_origin_id === doc.id);
                                const isSelected = selectedItem?.id === doc.id;

                                return (
                                    <div 
                                        key={doc.id}
                                        onClick={() => handleSelectItem(doc)}
                                        className={`
                                            group relative p-3 rounded border transition-all duration-200 cursor-pointer
                                            flex flex-col justify-between h-28
                                            ${isSelected 
                                                ? `bg-${currentThemeColor}-500/10 border-${currentThemeColor}-500 shadow-[0_0_10px_rgba(0,0,0,0.5)]` 
                                                : 'bg-slate-900/40 border-slate-800 hover:border-slate-600 hover:bg-slate-800'
                                            }
                                        `}
                                    >
                                        <div className="flex justify-between items-start">
                                            <DocumentTextIcon className={`h-6 w-6 ${isSelected ? `text-${currentThemeColor}-400` : 'text-slate-600'}`} />
                                            {isPublished && (
                                                <div className="flex h-2 w-2">
                                                    <span className={`animate-ping absolute inline-flex h-2 w-2 rounded-full bg-${currentThemeColor}-400 opacity-75`}></span>
                                                    <span className={`relative inline-flex rounded-full h-2 w-2 bg-${currentThemeColor}-500`}></span>
                                                </div>
                                            )}
                                        </div>
                                        <div className="mt-2">
                                            <span className={`block text-[10px] font-bold uppercase leading-tight line-clamp-2 ${isSelected ? 'text-white' : 'text-slate-400'}`}>
                                                {doc.name}
                                            </span>
                                        </div>
                                        <div className="text-[9px] text-slate-600 font-bold uppercase mt-1 text-right">
                                            {(doc.size / 1024).toFixed(1)} KB
                                        </div>
                                    </div>
                                );
                            })}
                        </div>

                        {displayedItems.folders.length === 0 && displayedItems.files.length === 0 && (
                            <div className="flex flex-col items-center justify-center h-48 text-slate-600 opacity-50">
                                <TerminalIcon className="h-8 w-8 mb-2" />
                                <span className="font-bold text-xs uppercase tracking-widest">Sector Vacío</span>
                            </div>
                        )}
                    </div>
                </section>

                <aside className="w-96 bg-[#080f1e] border-l border-slate-800 flex flex-col shadow-2xl relative z-20">
                    <div className={`h-1 w-full bg-gradient-to-r from-transparent via-${currentThemeColor}-500 to-transparent opacity-50`}></div>

                    {selectedItem || selectedFolder ? (
                        <div className="flex-1 flex flex-col p-6 animate-fade-in">
                            <div className="flex items-start gap-4 mb-6">
                                <div className={`p-3 rounded bg-${currentThemeColor}-900/20 border border-${currentThemeColor}-500/30`}>
                                    {selectedItem ? <DocumentTextIcon className={`h-8 w-8 text-${currentThemeColor}-400`} /> : <FolderIcon className={`h-8 w-8 text-${currentThemeColor}-400`} />}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <h2 className="text-sm font-extrabold text-white uppercase break-words leading-tight tracking-wide">
                                        {selectedItem ? selectedItem.name : selectedFolder?.name}
                                    </h2>
                                    <p className="text-[10px] text-slate-500 font-bold uppercase mt-1">
                                        {selectedItem ? `ID: ${selectedItem.id.slice(0, 8)}...` : `TIPO: CONTENEDOR`}
                                    </p>
                                </div>
                            </div>

                            <div className={`
                                mb-6 p-4 rounded-lg border-2 border-dashed
                                ${isCurrentPublished ? `border-${currentThemeColor}-500/50 bg-${currentThemeColor}-500/5` : 'border-slate-700 bg-slate-900/50'}
                            `}>
                                <div className="flex justify-between items-center mb-2">
                                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Estado de Conexión</span>
                                    {isCurrentPublished ? (
                                        <span className={`text-xs font-extrabold text-${currentThemeColor}-400 uppercase flex items-center gap-1`}>
                                            ● ACTIVO
                                        </span>
                                    ) : (
                                        <span className="text-xs font-extrabold text-slate-500 uppercase">○ INACTIVO</span>
                                    )}
                                </div>

                                {selectedItem && isCurrentPublished && (() => {
                                    const publishedInfo = publishedList.find(p => p.uad_origin_id === selectedItem.id);
                                    return publishedInfo && (
                                        <div className="space-y-1">
                                            <div className="flex justify-between text-[10px] font-bold uppercase border-b border-slate-700/50 pb-1"><span className="text-slate-500">CÓDIGO:</span><span className="text-white">{publishedInfo.code || 'N/A'}</span></div>
                                            <div className="flex justify-between text-[10px] font-bold uppercase border-b border-slate-700/50 pb-1"><span className="text-slate-500">ÁREA:</span><span className="text-white truncate max-w-[150px]">{publishedInfo.area}</span></div>
                                            <div className="flex justify-between text-[10px] font-bold uppercase border-b border-slate-700/50 pb-1"><span className="text-slate-500">VER:</span><span className="text-white">{publishedInfo.version}</span></div>
                                            <div className="flex justify-between text-[10px] font-bold uppercase"><span className="text-slate-500">ESTADO:</span><span className={`text-${publishedInfo.status === 'Caduco' ? 'red-500' : 'white'}`}>{publishedInfo.status}</span></div>
                                        </div>
                                    );
                                })()}

                                {selectedFolder && isCurrentPublished && (() => {
                                    const publishedInfo = publishedFoldersList.find(p => p.origin_folder_id === selectedFolder.id);
                                    return publishedInfo && (
                                        <div className="space-y-1">
                                            <div className="flex justify-between text-[10px] font-bold uppercase border-b border-slate-700/50 pb-1"><span className="text-slate-500">TIPO:</span><span className="text-white">CARPETA PUBLICA</span></div>
                                            <div className="flex justify-between text-[10px] font-bold uppercase"><span className="text-slate-500">ÁREA:</span><span className="text-white truncate max-w-[150px]">{publishedInfo.area}</span></div>
                                        </div>
                                    );
                                })()}
                            </div>

                            <div className="space-y-4 mb-8 flex-1">
                                <label className="block">
                                    <div className="flex justify-between items-center mb-1">
                                        <span className="text-[10px] font-bold text-slate-400 uppercase block tracking-wide">Área Designada</span>
                                        {isLoadingAreas && <span className={`text-[9px] text-${currentThemeColor}-400 animate-pulse`}>SINC...</span>}
                                    </div>
                                    <select 
                                        className="w-full bg-[#050b14] border border-slate-700 rounded text-slate-300 text-xs p-2 font-bold uppercase focus:border-white focus:outline-none disabled:opacity-50"
                                        value={publishForm.area}
                                        onChange={e => setPublishForm({...publishForm, area: e.target.value})}
                                        disabled={isLoadingAreas || areas.length === 0}
                                    >
                                        {areas.length === 0 && !isLoadingAreas && <option value="">Sin Áreas Disponibles</option>}
                                        {areas.map(area => <option key={area} value={area}>{area}</option>)}
                                    </select>
                                </label>

                                {selectedItem && (
                                    <>
                                        <div className="grid grid-cols-2 gap-4">
                                            <label className="block">
                                                <span className="text-[10px] font-bold text-slate-400 uppercase mb-1 block tracking-wide">Código Doc</span>
                                                <input type="text" className="w-full bg-[#050b14] border border-slate-700 rounded text-slate-300 text-xs p-2 font-bold uppercase focus:border-white focus:outline-none" placeholder="AUTO" value={publishForm.code} onChange={e => setPublishForm({...publishForm, code: e.target.value})} />
                                            </label>
                                            <label className="block">
                                                <span className="text-[10px] font-bold text-slate-400 uppercase mb-1 block tracking-wide">Versión</span>
                                                <input type="text" className="w-full bg-[#050b14] border border-slate-700 rounded text-slate-300 text-xs p-2 font-bold uppercase focus:border-white focus:outline-none" value={publishForm.version} onChange={e => setPublishForm({...publishForm, version: e.target.value})} />
                                            </label>
                                        </div>
                                        <label className="block">
                                            <span className="text-[10px] font-bold text-slate-400 uppercase mb-1 block tracking-wide">Estado Documento</span>
                                            <select className="w-full bg-[#050b14] border border-slate-700 rounded text-slate-300 text-xs p-2 font-bold uppercase focus:border-white focus:outline-none" value={publishForm.status} onChange={e => setPublishForm({...publishForm, status: e.target.value})} >
                                                <option value="Vigente">VIGENTE</option>
                                                <option value="Caduco">CADUCO</option>
                                            </select>
                                        </label>
                                    </>
                                )}
                            </div>

                            {statusMessage && (
                                <div className={`mb-4 p-3 text-center text-xs font-bold uppercase rounded border ${
                                    statusMessage.type === 'success' ? 'bg-green-900/30 border-green-500 text-green-400' :
                                    statusMessage.type === 'error' ? 'bg-red-900/30 border-red-500 text-red-400' :
                                    'bg-blue-900/30 border-blue-500 text-blue-400'
                                }`}>
                                    {statusMessage.text}
                                </div>
                            )}

                            <div className="mt-auto">
                                {isCurrentPublished ? (
                                    <button 
                                        onClick={handleUnpublish}
                                        disabled={isProcessing}
                                        className="w-full py-4 bg-red-900/20 border border-red-600 text-red-500 font-extrabold tracking-widest hover:bg-red-900/40 hover:text-red-400 transition-all uppercase flex items-center justify-center gap-2 group"
                                    >
                                        {isProcessing ? <RefreshIcon className="h-4 w-4 animate-spin"/> : <XCircleIcon className="h-5 w-5 group-hover:scale-110 transition-transform"/>}
                                        TERMINAR ENLACE
                                    </button>
                                ) : (
                                    <button 
                                        onClick={handlePublish}
                                        disabled={isProcessing || !publishForm.area}
                                        className={`w-full py-4 bg-${currentThemeColor}-600 hover:bg-${currentThemeColor}-500 text-white font-extrabold tracking-widest transition-all uppercase flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(0,0,0,0.5)] hover:shadow-[0_0_20px_rgba(var(--${currentThemeColor}-rgb),0.4)] disabled:opacity-50 disabled:cursor-not-allowed`}
                                    >
                                        {isProcessing ? <RefreshIcon className="h-4 w-4 animate-spin"/> : <GlobeAltIcon className="h-5 w-5 animate-pulse"/>}
                                        INICIAR ENLACE
                                    </button>
                                )}
                            </div>

                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col items-center justify-center text-slate-600 p-8 text-center opacity-50">
                            <div className="mb-4 relative">
                                <div className="absolute inset-0 bg-slate-500 blur-xl opacity-20 rounded-full"></div>
                                <InformationCircleIcon className="h-16 w-16 relative z-10" />
                            </div>
                            <h3 className="font-bold text-sm uppercase mb-2 tracking-widest">ESPERANDO ENTRADA</h3>
                            <p className="text-xs font-bold uppercase max-w-[200px]">Seleccione un archivo o use el icono de engranaje en una carpeta para configurar el enlace.</p>
                        </div>
                    )}
                </aside>
            </div>
        </div>
    );
};

