                            localStorage.setItem(notificationId, 'true');
                        }
                    }
                });
            });
        });
    };
    checkUpcomingAudits();
    const intervalId = setInterval(checkUpcomingAudits, 60 * 1000);
    return () => { clearInterval(intervalId); };
  }, [user, audits]);

