  const [interimTranscript, setInterimTranscript] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [isSupported, setIsSupported] = useState(true);
  const [copySuccess, setCopySuccess] = useState(false);

  // Refs para control de flujo
  const isListeningRef = useRef(false);
  const recognitionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // CRÍTICO: Este Set rastrea qué índices de la sesión actual ya fueron procesados como finales
  // para evitar el efecto de duplicidad "HOLA HOLA HOLA"
  const finalizedIndicesRef = useRef<Set<number>>(new Set());

  useEffect(() => {
    // Check browser support
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      setIsSupported(false);
      setError("Tu navegador no soporta la API de reconocimiento de voz nativa.");
      return;
    }

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();

    recognition.continuous = true; 
    recognition.interimResults = true; 
    recognition.lang = 'es-ES'; 

    recognition.onstart = () => {
      setIsListening(true);
      setError(null);
      // Al iniciar una sesión (nueva o por reinicio), limpiamos los índices de esa sesión específica
      finalizedIndicesRef.current.clear();
    };

    recognition.onresult = (event: any) => {
      let interim = '';
      let newFinals = '';

      // Iteramos desde el resultIndex (el primer resultado que cambió en este evento)
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        const result = event.results[i];
        const text = result[0].transcript;

        if (result.isFinal) {
          // Solo procesamos si no hemos visto este índice antes en esta sesión
          if (!finalizedIndicesRef.current.has(i)) {
            newFinals += text;
            finalizedIndicesRef.current.add(i);
          }
        } else {
          interim += text;
        }
      }

      // Si hay texto final nuevo, lo añadimos al estado principal una sola vez
      if (newFinals) {
        setTranscript(prev => (prev + ' ' + newFinals).trim());
      }

      setInterimTranscript(interim);

      // Auto-scroll al final
      if (scrollRef.current) {
        scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
      }
    };

    recognition.onerror = (event: any) => {
      if (event.error === 'not-allowed') {
        setError("Permiso de micrófono denegado.");
        isListeningRef.current = false;
        setIsListening(false);
      } else if (event.error !== 'no-speech' && event.error !== 'aborted') {
        setError(`Error de captura: ${event.error}`);
      }
    };

    recognition.onend = () => {
      // Si el usuario no ha pulsado detener, reiniciamos automáticamente (evita cortes por silencio largo)
      if (isListeningRef.current) {
         try {
             recognition.start();
         } catch (e) {
             setIsListening(false);
             isListeningRef.current = false;
         }
      } else {
         setIsListening(false);
      }
    };

    recognitionRef.current = recognition;

    return () => {
      isListeningRef.current = false;
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  const toggleListening = () => {
    if (isListeningRef.current) {
      isListeningRef.current = false;
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      isListeningRef.current = true;
      try {
        recognitionRef.current?.start();
        setIsListening(true);
        setError(null);
      } catch (err) {
        isListeningRef.current = false;
        setIsListening(false);
      }
    }
  };

  const handleCopy = () => {
    if (!transcript) return;
    navigator.clipboard.writeText(transcript);
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const handleClear = () => {
    if (window.confirm("¿Vaciar el registro de la bitácora?")) {
        setTranscript('');
        setInterimTranscript('');
        finalizedIndicesRef.current.clear();
    }
  };

  if (!isSupported) {
    return (
        <div className="flex items-center justify-center h-full text-red-500 bg-light-bg dark:bg-dark-bg p-8 rounded-lg border border-red-500/50">
            <XCircleIcon className="h-12 w-12 mr-4" />
            <div>
                <h2 className="text-xl font-bold">Navegador No Soportado</h2>
                <p>{error}</p>
            </div>
        </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-6rem)] gap-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-light-card dark:bg-dark-card p-6 rounded-lg border border-light-border dark:border-dark-border shadow-md">
        <div>
            <h1 className="text-3xl font-bold flex items-center gap-3 text-light-text dark:text-dark-text">
                <span className={`flex h-4 w-4 rounded-full ${isListening ? 'bg-red-500 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.8)]' : 'bg-gray-400'}`}></span>
                Bitácora de Voz
            </h1>
            <p className="text-light-text-secondary dark:text-dark-text-secondary mt-1 font-mono text-sm uppercase tracking-tighter">
                SISTEMA DE TRANSCRIPCIÓN ANTI-DUPLICADOS v1.3
            </p>
        </div>

        <div className="flex items-center gap-3 mt-4 sm:mt-0">
            <button
                onClick={toggleListening}
                className={`flex items-center gap-2 px-6 py-3 rounded-md font-bold transition-all uppercase tracking-wider ${
                    isListening 
                    ? 'bg-red-500/10 text-red-500 border border-red-500 hover:bg-red-500/20 shadow-[0_0_15px_rgba(239,68,68,0.4)]' 
                    : 'bg-brand-primary text-white hover:bg-brand-secondary shadow-lg'
                }`}
            >
                <MicrophoneIcon className={`h-5 w-5 ${isListening ? 'animate-bounce' : ''}`} />
                {isListening ? 'PAUSAR ESCUCHA' : 'ACTIVAR MICRÓFONO'}
            </button>
        </div>
      </div>

      <div className="flex-1 bg-[#0a0f18] rounded-lg border border-slate-800 shadow-inner relative overflow-hidden flex flex-col font-mono">
        <div className="absolute inset-0 pointer-events-none z-10 opacity-[0.05]" 
             style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }}>
        </div>

        <div className="bg-slate-900 px-4 py-2 border-b border-slate-800 flex justify-between items-center text-[10px] text-slate-500 select-none font-bold tracking-widest">
            <span>TERMINAL_LOG_AUDIT.txt</span>
            <span className={isListening ? 'text-green-500' : 'text-slate-600'}>{isListening ? '● CAPTURA EN TIEMPO REAL' : '○ SISTEMA EN STANDBY'}</span>
        </div>

        <div ref={scrollRef} className="flex-1 p-6 overflow-y-auto custom-scrollbar relative z-0">
            {transcript || interimTranscript ? (
