                    <MicrophoneIcon className="h-16 w-16 mb-4 opacity-10" />
                    <p className="text-sm font-bold uppercase tracking-widest opacity-20">Inicia el micrófono para transcribir...</p>
                </div>
            )}
        </div>

        <div className="bg-slate-900 p-3 border-t border-slate-800 flex justify-end gap-3 z-20">
            <button 
                onClick={handleCopy} 
                disabled={!transcript}
                className="flex items-center gap-2 px-4 py-2 bg-slate-800 text-slate-300 rounded hover:bg-slate-700 disabled:opacity-30 text-[10px] font-black uppercase transition-colors border border-slate-700"
            >
                {copySuccess ? <CheckCircleIcon className="h-4 w-4 text-green-500"/> : <ClipboardListIcon className="h-4 w-4"/>}
                {copySuccess ? 'COPIADO AL PORTAPAPELES' : 'COPIAR TRANSCRIPCIÓN'}
            </button>
            <button 
                onClick={handleClear}
                className="flex items-center gap-2 px-4 py-2 bg-red-900/10 text-red-500 border border-red-900/30 rounded hover:bg-red-900/20 text-[10px] font-black uppercase transition-colors"
