        }
      }

      // Guardamos lo que llevamos de esta ráfaga de forma definitiva en el ref
      currentSessionFinalRef.current = sessionFinal.trim();

      // El estado visual es: Todo el pasado + lo reconstruido de esta sesión
      const fullTranscript = (historyRef.current + ' ' + currentSessionFinalRef.current).trim();
      setTranscript(fullTranscript);
      setInterimTranscript(sessionInterim);

      // Scroll automático suave
      if (scrollRef.current) {
        scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
      }
    };

    recognition.onerror = (event: any) => {
      if (event.error === 'not-allowed') {
        setError("Acceso al micrófono denegado.");
        isListeningRef.current = false;
        setIsListening(false);
      } else if (event.error !== 'no-speech' && event.error !== 'aborted') {
        setError(`Error del motor: ${event.error}`);
      }
    };

    recognition.onend = () => {
      // "BAKE": Al terminar una ráfaga (por silencio largo o pausa), 
      // consolidamos lo finalizado de esta ráfaga en el historial permanente.
      if (currentSessionFinalRef.current) {
          historyRef.current = (historyRef.current + ' ' + currentSessionFinalRef.current).trim();
          currentSessionFinalRef.current = '';
      }

      // Auto-reinicio para emular escucha infinita sin duplicar texto
      if (isListeningRef.current) {
         try {
             recognition.start();
         } catch (e) {
             setIsListening(false);
             isListeningRef.current = false;
         }
      } else {
         setIsListening(false);
      }
    };

    recognitionRef.current = recognition;

    return () => {
      isListeningRef.current = false;
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  const toggleListening = () => {
    if (isListeningRef.current) {
      isListeningRef.current = false;
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      isListeningRef.current = true;
      try {
        recognitionRef.current?.start();
        setIsListening(true);
        setError(null);
      } catch (err) {
        isListeningRef.current = false;
        setIsListening(false);
      }
    }
  };

  const handleCopy = () => {
    if (!transcript) return;
    navigator.clipboard.writeText(transcript);
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const handleClear = () => {
    if (window.confirm("¿Vaciar el historial de la bitácora?")) {
        historyRef.current = '';
        currentSessionFinalRef.current = '';
        setTranscript('');
        setInterimTranscript('');
    }
  };

  if (!isSupported) {
    return (
        <div className="flex items-center justify-center h-full text-red-500 bg-light-bg dark:bg-dark-bg p-8 rounded-lg border border-red-500/50">
            <XCircleIcon className="h-12 w-12 mr-4" />
